#!/usr/bin/env node
/* Books-2 batch2-part2 ENT wave: Dhingra ENT 8th topic map, own words, new MCQs only. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Dhingra Diseases of ENT 8th Edition (topic map; text rewritten, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
function cmp(lt, lp, rt, rp) { return { kind: "compare", left: { title: lt, points: lp }, right: { title: rt, points: rp } }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("ent-sinusitis", "Sinusitis and its complications", "sinusitis_complications_ent", "Sinusitis and Its Complications",
 ["Acute bacterial sinusitis", "Orbital cellulitis sinusitis", "Cavernous sinus thrombosis", "FESS"],
 [step("**Acute rhinosinusitis** is usually viral (under ten days, improving), while acute bacterial disease declares by three patterns: persistent symptoms over ten days without improvement, severe onset (fever over 39, purulence and facial pain for three to four days), or double worsening after initial recovery. Maxillary sinus dominates adults; ethmoids dominate children because frontal and sphenoid sinuses pneumatise later (frontal from about age seven onward). Ostiomeatal obstruction, viral ciliary failure and allergy underpin most episodes.", "Cold over ten days, severe from start, or better then worse: bacterial sinusitis. Frontal sinuses arrive late in childhood."),
  step("Chronic disease and imaging discipline: CT is for complications, recurrence, surgery planning or immunocompromise, not routine colds. Examination and endoscopy show middle meatal pus, polyps or oedema. Antibiotics (local first line, e.g. amoxicillin patterns) reserve for bacterial criteria with analgesia, saline irrigation and intranasal steroids as symptomatic backbone. Dental roots (upper premolars and molars) infect maxillary sinus unilaterally, needing dental source control.", "Scan sinuses for complications or surgery, not every cold. One sided maxillary disease smells dental."),
  step("**Orbital complications** of ethmoid sinusitis (Chandler groups) escalate from preseptal cellulitis through orbital cellulitis, subperiosteal abscess, orbital abscess to cavernous sinus thrombosis. Proptosis, painful restricted eye movements, chemosis, vision change or bilateral signs are emergencies needing contrast CT, IV antibiotics and ENT ophthalmology drainage decisions. Children through thin lamina papyracea are classic victims.", "Swollen eye plus painful movements plus sinusitis is orbital emergency until scanned. Bilateral eye signs mean cavernous sinus."),
  step("Intracranial and bone complications include frontal osteomyelitis with forehead swelling (**Pott puffy tumour**), epidural and subdural empyema, meningitis, frontal lobe abscess and cavernous sinus thrombosis (bilateral ophthalmoplegia, chemosis, trigeminal signs, sepsis). Sphenoid disease threatens cavernous sinus, pituitary and carotid neighbours. Functional endoscopic sinus surgery (FESS) restores ostiomeatal ventilation in chronic or complicated disease refractory to medical therapy, respecting orbit and skull base landmarks.", "Puffy forehead over sinusitis is bone infection. FESS opens drainage; orbit and brain sit millimetres away.", tbl(["Chandler group", "Lesion", "Eye signs"], [["I", "Preseptal cellulitis", "Lid swelling, normal movements and vision"], ["II", "Orbital cellulitis", "Proptosis, chemosis, painful movement"], ["III", "Subperiosteal abscess", "Displacement, drainage often needed"], ["IV and V", "Orbital abscess, cavernous thrombosis", "Vision threat, bilateral signs in V"]]))],
 ["Bacterial sinusitis: 10 days, severe start, or double worsening", "Orbital warning: proptosis, ophthalmoplegia, vision change", "Pott puffy tumour is frontal bone osteomyelitis", "Unilateral maxillary sinusitis: check teeth"],
 "Mucociliary failure and ostial blockage stagnate secretions for bacterial growth, while valveless veins and paper thin lamina conduct infection to orbit and cavernous sinus, and diploic veins seed frontal bone and epidural spaces.",
 ["Viral versus bacterial rhinosinusitis by duration pattern", "Preseptal versus orbital cellulitis by eye movement and vision", "Odontogenic versus rhinogenic maxillary disease"],
 ["Nasendoscopy for meatal pus and polyps", "Contrast CT orbits and sinuses for complications", "MRI brain and sinuses for intracranial extension"],
 [mcq("bk2-ent-121", "Which course pattern best defines acute bacterial rhinosinusitis?", ["3 days improving cold", "Symptoms over 10 days without improvement, severe 3 to 4 day onset, or double worsening", "Any coloured discharge day 1", "Headache alone one week"], 1, "Guideline bacterial patterns are persistence, severity or biphasic worsening; coloured mucus alone early is viral. Antibiotics follow these patterns, not discharge colour.", ["Incorrect. Short improving illness is viral.", "Correct. Ten days, severe start, or double worsening.", "Incorrect. Colour does not equal bacterial day one.", "Incorrect. Headache alone fits many causes."], "Ten, severe, or worse again: bacterial."),
  mcq("bk2-ent-122", "Child with ethmoid sinusitis, proptosis, painful restricted eye movements and chemosis needs what first?", ["Oral antibiotics home", "Emergency contrast CT, IV antibiotics, ENT and ophthalmology care", "Reassure as preseptal", "Nasal drops only"], 1, "Post septal orbital cellulitis threatens vision and cavernous spread; imaging grades Chandler stage guiding drainage. Preseptal disease keeps normal movements, vision and no proptosis.", ["Incorrect. Orbital signs exceed oral home care.", "Correct. Scan, IV treat, joint specialist care.", "Incorrect. Movement pain excludes simple preseptal.", "Incorrect. Drops cannot treat orbit."], "Painful proptosed eye with sinusitis scans now."),
  mcq("bk2-ent-123", "Forehead swelling in adolescent with frontal sinusitis (Pott puffy tumour) represents what?", ["Allergy swelling", "Frontal bone osteomyelitis with subperiosteal abscess", "Insect bite", "Frontal polyp"], 1, "Pott puffy tumour is frontal osteomyelitis via diploic veins with subperiosteal collection, risking epidural abscess; it needs imaging, IV antibiotics and surgical drainage planning.", ["Incorrect. Allergy lacks fever bony swelling context.", "Correct. Frontal osteomyelitis collection.", "Incorrect. Bite lacks sinusitis linkage.", "Incorrect. Polyps live intranasally."], "Puffy forehead over bad sinus is bone pus."),
  mcq("bk2-ent-124", "Bilateral chemosis, ophthalmoplegia and sepsis after sinusitis indicate which complication?", ["Preseptal cellulitis", "Cavernous sinus thrombosis", "Conjunctivitis", "Dacryocystitis"], 1, "Cavernous sinuses communicate across midline, so bilateral eye signs with trigeminal involvement and septic course after sphenoid or ethmoid disease define this lethal thrombosis needing MRI/MRV and ICU care.", ["Incorrect. Preseptal is unilateral lid only.", "Correct. Cavernous sinus thrombosis bilateralises.", "Incorrect. Conjunctivitis spares movements and proptosis.", "Incorrect. Tear sac infection localises medial canthus."], "Both eyes involved: cavernous sinus clotting."),
  mcq("bk2-ent-125", "Persistent one sided foul maxillary sinusitis in adult should prompt examination of what?", ["Lower teeth", "Upper premolar and molar roots (odontogenic source)", "Tonsils", "Parotid"], 1, "Upper posterior tooth roots abut or protrude into maxillary floor; periapical infection or oroantral fistula after extraction sustains unilateral sinusitis until dental treatment plus sinus care.", ["Incorrect. Lower teeth drain elsewhere.", "Correct. Upper back teeth infect maxillary sinus.", "Incorrect. Tonsils cause pharyngeal symptoms.", "Incorrect. Parotid is cheek gland."], "One bad maxilla: look at upper teeth."),
  mcq("bk2-ent-126", "Frontal sinus is typically absent or rudimentary until about what age, shaping paediatric sinusitis patterns?", ["Birth fully formed", "Pneumatises through childhood, clinically relevant from about 6 to 7 years", "Age 30", "Never develops"], 1, "Ethmoid and maxillary sinuses exist at birth (ethmoid causing childhood orbital complications), sphenoid develops mid childhood and frontal last into teens, so frontal disease and Pott tumour are older child or adolescent problems.", ["Incorrect. Frontal sinus is not formed at birth.", "Correct. Frontal develops from school age.", "Incorrect. Thirty is far too late.", "Incorrect. Most adults have frontal sinuses (some aplasia)."], "Ethmoids trouble toddlers; frontals trouble teens."),
  mcq("bk2-ent-127", "FESS (functional endoscopic sinus surgery) aims principally to do what?", ["Remove all sinus mucosa", "Restore ventilation and mucociliary drainage at ostiomeatal complex", "Close sinuses permanently", "Replace antibiotics in acute viral colds"], 1, "FESS widens natural ostia and clears diseased ethmoid partitions preserving mucosa and cilia function for chronic or complicated disease failing medical therapy. It is not acute cold treatment.", ["Incorrect. Mucosa preservation is principle.", "Correct. Restore natural drainage pathways.", "Incorrect. Obliteration is rare salvage.", "Incorrect. Viral colds need no surgery."], "Open the natural doors, keep the lining."),
  mcq("bk2-ent-128", "Most common sinus involved in acute bacterial sinusitis of adults is what?", ["Frontal", "Maxillary", "Sphenoid isolated", "None"], 1, "Maxillary sinusitis dominates adult practice (large sinus, dependent ostium high on medial wall impairing drainage). Isolated sphenoid disease is uncommon but dangerous by neighbours.", ["Incorrect. Frontal follows maxillary frequency.", "Correct. Maxillary commonest.", "Incorrect. Isolated sphenoid is rare.", "Incorrect. Sinuses are the disease site."], "Maxillary wins adult sinusitis."),
  mcq("bk2-ent-129", "Danger neighbours making isolated sphenoid sinusitis high risk are what?", ["Teeth only", "Cavernous sinus, internal carotid, pituitary and optic nerve", "Parotid gland", "Tonsil"], 1, "Sphenoid walls border cavernous carotid, pituitary fossa and optic nerve, so infection or surgical slips threaten vision, major bleeding and hypopituitarism; deep vertex headache is clue.", ["Incorrect. Teeth neighbour maxillary floor.", "Correct. Carotid, pituitary, optic, cavernous sinus.", "Incorrect. Parotid is lateral face.", "Incorrect. Tonsil is oropharyngeal."], "Sphenoid sits among giants: respect it."),
  mcq("bk2-ent-130", "Routine CT scanning in uncomplicated acute viral rhinosinusitis is what?", ["Mandatory", "Not indicated; imaging reserved for complications, recurrence, immunocompromise or surgical planning", "Replaces examination", "Needed to colour discharge"], 1, "Imaging in simple colds shows incidental mucosal thickening without changing care and adds radiation; endoscopy and course patterns guide, scanning follows red flags.", ["Incorrect. Not for simple viral illness.", "Correct. Reserve CT for defined indications.", "Incorrect. Examination remains primary.", "Incorrect. Discharge colour never mandates scan."], "No red flags, no sinus scan.")]);

add("ent-sinonasal-tumours", "Sinonasal tumours and granulomatous conditions", "sinonasal_tumours_granulomatous", "Sinonasal Tumours and Granulomatous Conditions",
 ["Inverted papilloma", "Sinonasal malignancy", "Juvenile angiofibroma", "Granulomatosis polyangiitis nose"],
 [step("Benign sinonasal tumours present with unilateral obstruction, discharge and epistaxis. **Inverted papilloma** arises from lateral nasal wall or maxillary sinus in middle aged men, locally destructive with about 5 to 10 percent synchronous or metachronous squamous carcinoma association, needing complete endoscopic excision including bony origin drilling and long surveillance for recurrence. Osteomas (frontal, incidental) and juvenile angiofibroma (adolescent males) complete classic benign patterns.", "One sided middle aged mass is inverted papilloma until proven otherwise: remove fully, watch for years, some turn malignant."),
  step("**Juvenile nasopharyngeal angiofibroma** grows from sphenopalatine foramen region in teenage boys (androgen sensitive, almost exclusively male), causing recurrent heavy epistaxis and obstruction with vascular blush on imaging (CT erosion, MRI flow voids, angiography feeding vessels from internal maxillary). Biopsy in clinic is forbidden for haemorrhage risk; preoperative embolisation precedes endoscopic resection in modern pathways.", "Teen boy, blocked nose, flooding bleeds: angiofibroma. Image and embolise, never biopsy in clinic."),
  step("Sinonasal **malignancies** (squamous carcinoma commonest, adenocarcinoma in hardwood workers ethmoid, olfactory neuroblastoma from olfactory cleft, mucosal melanoma, lymphoma) present late with unilateral epistaxis, obstruction, facial pain, orbital invasion (proptosis, diplopia), loose teeth or palatal mass and anosmia. Nickel and hardwood dust, leather work and HPV or EBV associations vary by type. MRI distinguishes tumour from trapped secretions; CT maps bone; biopsy via endoscopy after imaging vascular lesions excluded.", "Wood dust gives ethmoid adenocarcinoma. Late one sided bleeding with eye or tooth signs is cancer until scoped and biopsied safely."),
  step("Granulomatous and destructive midline disease includes granulomatosis with polyangiitis (septal perforation, saddle, crusting), cocaine induced midline lesions (history, ANCA artefacts), extranodal NK or T cell lymphoma nasal type (EBV linked, necrotic midline, formerly lethal midline granuloma) and sarcoid or tuberculosis mimics. Workup biopsies necrotic edges repeatedly (often non diagnostic), ANCA, cultures and EBV studies with rheumatology and haematology. Rhinoscleroma and rhinosporidiosis are regional infective masses in endemic patterns.", "Midline nose destruction: vasculitis, cocaine, lymphoma or infection. Biopsy edges, test ANCA and EBV.", tbl(["Lesion","Patient","Hallmark"], [["Inverted papilloma", "Middle aged man, unilateral", "Recurs, malignant association"], ["Angiofibroma", "Teenage boy", "Vascular, epistaxis, no biopsy"], ["Adenocarcinoma ethmoid", "Hardwood worker", "Occupational dust"], ["NK T lymphoma nasal", "Midline necrosis", "EBV driven, destructive"]]))],
 ["Unilateral nasal mass in adult needs tumour pathway", "Angiofibroma: adolescent male, image, embolise, no biopsy", "Inverted papilloma recurs and can harbour carcinoma", "Hardwood dust causes ethmoid adenocarcinoma"],
 "HPV associated Schneiderian papilloma inverts into epithelium with local bone resorption, while angiogenesis rich fibrous tumours of adolescence regress or persist with androgen signals; occupational dusts deposit carcinogens on ethmoid mucosa over decades.",
 ["Inverted papilloma versus inflammatory polyp (laterality, age, imaging)", "Sinonasal cancer versus chronic sinusitis (unilateral red flags)", "GPA septal disease versus cocaine lesion (history, systemic features)"],
 ["Nasendoscopy and biopsy after vascular exclusion", "CT and MRI sinuses complementary (bone versus soft tissue)", "ANCA, EBV and tissue cultures in midline destruction"],
 [mcq("bk2-ent-131", "Unilateral lateral wall mass in 55 year old man recurring after removal, with focal hyperostosis on CT, most likely is what?", ["Ethmoid polyp", "Inverted papilloma", "Antrochoanal polyp", "Rhinitis swelling"], 1, "Inverted papilloma attaches laterally with bony reaction, recurs if origin not drilled, and associates with squamous carcinoma in up to about a tenth, mandating complete excision and surveillance.", ["Incorrect. Polyps are usually bilateral allergic.", "Correct. Inverted papilloma of lateral wall.", "Incorrect. Antrochoanal is youthful maxillary polyp.", "Incorrect. Turbinate swelling shrinks and is sensitive."], "One sided, recurs, bone spot: inverted papilloma."),
  mcq("bk2-ent-132", "Why is clinic biopsy forbidden in suspected juvenile angiofibroma?", ["Tumour is infectious", "Profuse haemorrhage from vascular tumour without control", "Biopsy spreads cancer", "It is always malignant"], 1, "Angiofibromas are dense vascular masses in adolescents where imaging is diagnostic and biopsy can flood; angiography with embolisation then resection in theatre is pathway.", ["Incorrect. Not infection issue.", "Correct. Biopsy can cause catastrophic bleeding.", "Incorrect. Seeding is not concern; bleeding is.", "Incorrect. It is benign histology."], "Vascular teen tumour: pictures, not biopsies."),
  mcq("bk2-ent-133", "Ethmoid adenocarcinoma occupational association is classically what?", ["Nickel refining only", "Hardwood dust exposure (furniture workers)", "Asbestos", "Coal mining"], 1, "Hardwood dust (beech, oak) deposited in olfactory and ethmoid region causes intestinal type adenocarcinoma after long latency; nickel instead associates squamous carcinoma of sinuses.", ["Incorrect. Nickel links squamous type.", "Correct. Hardwood dust, ethmoid adenocarcinoma.", "Incorrect. Asbestos is pleural and peritoneal.", "Incorrect. Coal is lung disease pattern."], "Carpenter ethmoid cancer from hardwood dust."),
  mcq("bk2-ent-134", "Inverted papilloma malignant association requiring surveillance is transformation or coexistence with what?", ["Melanoma", "Squamous cell carcinoma (about 5 to 10 percent)", "Lymphoma", "Sarcoma"], 1, "Synchronous or later squamous carcinoma within papilloma occurs in roughly a tenth spectrum, so histology of entire specimen and long endoscopic follow up are mandatory.", ["Incorrect. Melanoma is separate mucosal tumour.", "Correct. Squamous carcinoma association.", "Incorrect. Lymphoma arises independently midline.", "Incorrect. Sarcoma rare different tumour."], "Papilloma hides squamous cancer in one in ten."),
  mcq("bk2-ent-135", "Necrotic destructive midline nasal lesion with EBV positivity and systemic fever most suggests what?", ["GPA only", "Extranodal NK T cell lymphoma, nasal type", "Cocaine use excluded by EBV", "Simple perforation"], 1, "EBV driven NK T lymphoma destroys midface (old lethal midline granuloma) with necrosis and systemic symptoms, needing deep edge biopsies, EBV viral load and chemo radiation haematology care.", ["Incorrect. GPA lacks EBV driver and responds differently.", "Correct. NK T lymphoma nasal type.", "Incorrect. Cocaine may coexist but EBV tumour dominates picture.", "Incorrect. Destruction exceeds simple hole."], "Midline melts with EBV: lymphoma."),
  mcq("bk2-ent-136", "MRI in sinonasal tumour planning adds what over CT chiefly?", ["Bone detail", "Separates tumour from retained secretions and maps orbit, dura and perineural spread", "Shows teeth better", "No added value"], 1, "Secretions trapped behind tumour mimic mass on CT; MRI signal separates them and defines orbital, intracranial and skull base invasion for staging and resection or radiation fields.", ["Incorrect. CT wins bone anatomy.", "Correct. Soft tissue separation and invasion mapping.", "Incorrect. Dental bone is CT strength.", "Incorrect. MRI is decisive for extent."], "CT for bone, MRI for tumour truth."),
  mcq("bk2-ent-137", "Olfactory neuroblastoma arises from which site and often presents how?", ["Maxillary floor; tooth pain", "Olfactory cleft high in nose; unilateral obstruction, epistaxis, anosmia", "Nasopharynx; ear effusion", "Frontal skin; lump"], 1, "Esthesioneuroblastoma grows from olfactory epithelium superiorly (Kadish staging by extension), often dumbbell into anterior cranial fossa, treated with surgery plus radiation pathways.", ["Incorrect. Maxillary tumours cause dental signs.", "Correct. High olfactory origin with smell loss.", "Incorrect. Nasopharyngeal cancer gives that pattern.", "Incorrect. Skin tumours differ."], "Smell gone, high mass: olfactory tumour."),
  mcq("bk2-ent-138", "Saddle nose with septal perforation, crusting plus haematuria and lung nodules points to which systemic disease needing ANCA?", ["Sarcoidosis only", "Granulomatosis with polyangiitis", "Relapsing polychondritis only", "Lupus pernio"], 1, "Upper airway destruction with pulmonary renal small vessel vasculitis and PR3 ANCA defines GPA; nasal limited disease still scars septum and saddle before systemic declaration.", ["Incorrect. Sarcoid infiltrates but renal lung pattern differs.", "Correct. GPA vasculitis triad pattern.", "Incorrect. Polychondritis attacks cartilage including ears.", "Incorrect. Lupus pernio is sarcoid skin of nose, not perforating vasculitis."], "Nose, lungs, kidneys bleed: GPA."),
  mcq("bk2-ent-139", "Frontal sinus osteoma is most commonly discovered how and managed how?", ["Pain emergency; immediate resection all", "Incidental imaging finding; observe unless obstructing, growing or symptomatic", "Epistaxis flood; embolise", "In children with fever"], 1, "Slow benign bone tumours are frequent incidental findings; surgery follows sinus obstruction, mucocele, orbital or intracranial growth, or headache attribution after evaluation.", ["Incorrect. Most are silent findings.", "Correct. Incidental, observe selectively.", "Incorrect. Not vascular bleeders.", "Incorrect. Adult incidental pattern."], "Quiet bone lump on scan: watch it."),
  mcq("bk2-ent-140", "Cocaine induced midline lesion is separated from GPA most helpfully by what?", ["Perforation size", "History and toxicology, often palatal necrosis, ANCA can be atypically positive in cocaine use", "Age only", "Crusting absent"], 1, "Cocaine (and levamisole adulterant) destroys septum and palate mimicking vasculitis serologically; confidential history, drug testing with consent and absence of systemic vasculitis organs guide, and cessation is treatment.", ["Incorrect. Sizes overlap completely.", "Correct. Exposure history and systemic absence.", "Incorrect. Age overlaps.", "Incorrect. Both crust heavily."], "Ask the powder question in midline destruction.")]);

add("ent-facial-trauma", "Maxillofacial fractures and CSF rhinorrhoea", "maxillofacial_fractures_csf", "Maxillofacial Fractures and CSF Rhinorrhoea",
 ["Le Fort fractures", "Zygomatic fractures", "CSF rhinorrhoea", "Orbital blowout"],
 [step("Facial trauma triage protects airway (blood, swelling, displaced maxilla), cervical spine, eyes and brain before bones. **Zygomatic** fractures flatten cheek, restrict mouth opening (coronoid impingement), cause infraorbital numbness and diplopia from orbital floor involvement. Naso orbital ethmoid injuries telescope the nasal bridge with telecanthus. Mandible fractures (second commonest facial bone after nasal) malocclude, favour paired fractures (symphysis plus condyle ring), and threaten airway in bilateral parasymphyseal (flail, tongue falls back) injuries.", "Airway, spine, eyes, brain first. Flat cheek plus numb plus trismus is zygoma. Broken jaw breaks in two places."),
  step("**Le Fort** midface fractures separate facial skeleton at levels: I low transverse above teeth (floating palate), II pyramidal through infraorbital rims and nasal bridge, III craniofacial disjunction through zygomatic arches and orbits (floating face). All can bleed massively and obstruct airway; mobile maxilla on examination (gentle, once) and malocclusion with CSF leak risk (cribriform in II or III) define them. CT facial bones with 3D reconstruction plans fixation restoring occlusion first, then buttresses.", "Le Fort one floats palate, two floats nose pyramid, three floats whole face. Fix occlusion first."),
  step("**Orbital blowout** fractures floor (or medial wall) into sinuses after blunt globe injury, trapping inferior rectus causing diplopia worse on upgaze, enophthalmos later, infraorbital numbness and oculocardiac bradycardia in children (trapdoor white eyed blowout needs urgent release). Urgent indications: muscle entrapment, large floor defect with enophthalmos risk, retrobulbar haemorrhage (orbital compartment syndrome with proptosis, tense globe, vision loss needing lateral canthotomy). Retrobulbar bleed must not wait for CT when vision threatened.", "Child cannot look up, feels sick and slow pulse after eye hit: trapdoor, operate urgently. Tight proptosed eye bleeding behind globe: cut canthus now."),
  step("**CSF rhinorrhoea** follows anterior skull base fractures (cribriform, frontal sinus posterior table, sphenoid) presenting as clear watery unilateral discharge increasing leaning forward, salty taste, reservoir sign, confirmed by beta 2 transferrin (not glucose strips). Most traumatic leaks close within a week with head elevation and avoiding straining or nose blowing; persistent, recurrent meningitis or large defects need endoscopic repair. Prophylactic antibiotics do not prevent meningitis and are generally withheld. Beta trace protein is alternative test where available.", "Clear watery nose drip after head injury is CSF until beta 2 transferrin says no. Most seal in a week sitting up.", tbl(["Fracture", "Separation level", "Clinical anchor"], [["Le Fort I", "Above teeth, palate mobile", "Floating palate, malocclusion"], ["Le Fort II", "Pyramidal midface", "Nasal and infraorbital steps, CSF risk"], ["Le Fort III", "Craniofacial disjunction", "Floating face, telecanthus pattern"], ["Zygoma", "Cheek tetrapod", "Flattening, numbness, trismus"]]))],
 ["Le Fort III floats entire face off skull", "White eyed blowout in child is surgical urgency", "CSF test is beta 2 transferrin, not glucose", "Retrobulbar haemorrhage: canthotomy before CT when vision dying"],
 "Hydraulic globe pressure fractures thin orbital walls sparing rim, while midface buttress failure at Le Fort levels dissociates occlusion bearing skeleton; dural tears at cribriform leak CSF along olfactory fila pathways.",
 ["Orbital blowout versus globe rupture examination separation", "CSF rhinorrhoea versus allergic clear discharge (beta 2 transferrin)", "Zygomatic versus maxillary fracture by arch and buttress signs"],
 ["CT face with fine cuts and 3D, CT head and c spine by trauma protocol", "Beta 2 transferrin on collected fluid", "Ophthalmology assessment, ocular motility and vision charting"],
 [mcq("bk2-ent-141", "Le Fort III fracture is defined by what separation?", ["Palate only", "Craniofacial disjunction: entire facial skeleton separated from skull base", "Mandible condyle", "Nasal bones alone"], 1, "Le Fort III runs through zygomatic arches, lateral orbits and nasal bridge separating face from cranium (floating face) with highest CSF and airway risk. I separates palate, II pyramids midface.", ["Incorrect. Palate level is Le Fort I.", "Correct. Whole face disjoined in III.", "Incorrect. Mandible is lower face separate system.", "Incorrect. Nasal only is isolated nasal fracture."], "Three floats the whole face."),
  mcq("bk2-ent-142", "Child with eye trauma, minimal bruising, cannot elevate eye, nausea and bradycardia needs what?", ["Discharge with drops", "Urgent orbital CT and surgical release of trapdoor blowout with entrapped muscle", "Review in 6 weeks", "Patch and reassure"], 1, "White eyed blowout: elastic child bone trapdoors inferior rectus causing oculocardiac reflex; delay necroses muscle and fixes diplopia, so urgent ophthalmic maxillofacial surgery.", ["Incorrect. Entrapment worsens hourly.", "Correct. Urgent trapdoor release.", "Incorrect. Weeks delay causes permanent restriction.", "Incorrect. Patch hides emergency."], "Quiet white eye that cannot look up operates tonight."),
  mcq("bk2-ent-143", "Clear watery unilateral nasal discharge after frontal trauma, salty taste, is confirmed as CSF by which test?", ["Glucose oxidase strip", "Beta 2 transferrin (or beta trace protein)", "Culture", "Specific gravity"], 1, "Beta 2 transferrin is CSF specific (also perilymph) and reliable; glucose strips false positive from tears and mucus and are obsolete for this use. Collect fluid without contaminating blood where possible.", ["Incorrect. Glucose strips are unreliable.", "Correct. Beta 2 transferrin confirms CSF.", "Incorrect. Culture grows contaminants, not origin.", "Incorrect. Gravity cannot identify CSF."], "Transferrin, not sugar, proves CSF."),
  mcq("bk2-ent-144", "Proptosis, tense rock hard globe, severe pain and falling vision after facial trauma demand what before imaging?", ["Wait for CT", "Immediate lateral canthotomy and cantholysis for orbital compartment syndrome from retrobulbar haemorrhage", "IV antibiotics first", "Eye patch pressure"], 1, "Retrobulbar bleed raises intraorbital pressure strangling optic nerve and retina; bedside canthotomy releases orbit within minutes and cannot await scans when clinical syndrome is present.", ["Incorrect. Imaging delay blinds.", "Correct. Cut canthus immediately.", "Incorrect. Antibiotics do not decompress.", "Incorrect. Pressure worsens compartment."], "Tight blind eye: release orbit at bedside."),
  mcq("bk2-ent-145", "Most traumatic CSF rhinorrhoea management in first week is what?", ["Immediate surgery all", "Conservative: head up, avoid straining, sneezing suppression, no nose blowing; surgery if persistent or meningitis", "Prophylactic antibiotics mandatory", "Lumbar drain for all day one"], 1, "Majority seal spontaneously within seven to ten days with elevation and pressure precautions; antibiotics do not prevent meningitis and select resistance. Persistent leaks, pneumocephalus or meningitis go endoscopic repair pathways.", ["Incorrect. Most close without surgery.", "Correct. Conservative first week, repair if persists.", "Incorrect. Prophylaxis not recommended routinely.", "Incorrect. Drains are selective specialist tools."], "Sit up, do not strain, most leaks seal."),
  mcq("bk2-ent-146", "Bilateral parasymphyseal mandibular fractures threaten airway chiefly because what?", ["Teeth aspiration only", "Anterior mandible flail loses tongue support, tongue falls back obstructing", "Bleeding always massive", "Cervical spine always broken"], 1, "Glossoptosis from detached genial muscle support obstructs supine airway; positioning, suction, jaw support and definitive airway planning precede fixation. Ring principle also mandates searching second fracture.", ["Incorrect. Teeth risk secondary.", "Correct. Tongue falls back from flail segment.", "Incorrect. Bleeding varies.", "Incorrect. Spine checked but separate mechanism."], "Broken jaw both sides drops the tongue."),
  mcq("bk2-ent-147", "Cheek flattening, infraorbital numbness, trismus and diplopia after punch indicate which fracture?", ["Nasal", "Zygomatic complex (tripod) fracture with orbital floor involvement", "Le Fort I only", "Frontal sinus only"], 1, "Tetrapod zygoma fractures displace at frontozygomatic, infraorbital, zygomaticomaxillary and arch points causing this sign cluster; CT guides reduction (Gillies approach patterns) and floor repair indications.", ["Incorrect. Nasal injury centres nose.", "Correct. Zygomatic complex fracture.", "Incorrect. Le Fort I floats palate.", "Incorrect. Frontal alone lacks cheek pattern."], "Flat numb cheek that cannot open: zygoma."),
  mcq("bk2-ent-148", "In midface fracture repair, the functional priority restored first is what?", ["Cheek contour cosmetics", "Dental occlusion (then facial buttresses and height)", "Nasal airflow", "Tear drainage"], 1, "Maxillomandibular fixation re establishes premorbid occlusion as foundation; buttress plating then restores vertical and projection dimensions. Cosmetic sequencing follows function.", ["Incorrect. Contour follows occlusion.", "Correct. Occlusion first in repair.", "Incorrect. Airway matters but bite anchors repair.", "Incorrect. Lacrimal issues secondary repair."], "Bite right first, face follows."),
  mcq("bk2-ent-149", "Reservoir sign in CSF rhinorrhoea refers to what?", ["Fluid in sphenoid on scan", "Gush of clear fluid on leaning forward after pooling in sinus", "Reservoir of infection", "Beta protein level"], 1, "CSF collects in frontal or sphenoid sinus while upright or supine then drains in gush on bending (reservoir or teapot sign), classic history separating from continuous rhinitis drip.", ["Incorrect. Scan pooling is separate finding.", "Correct. Bending releases pooled CSF gush.", "Incorrect. Not infection term.", "Incorrect. Lab test differs."], "Lean forward, clear gush: pooled CSF."),
  mcq("bk2-ent-150", "Entrapped inferior rectus in blowout causes diplopia worst in which gaze and why?", ["Downgaze; muscle stretched", "Upgaze; tethered inferior rectus cannot relax and globe cannot elevate", "Lateral gaze; medial wall", "All gazes equally from swelling only"], 1, "Floor fracture traps or tethers inferior rectus so elevation fails and diplopia peaks looking up, with forced duction restriction confirming mechanical cause over nerve palsy.", ["Incorrect. Elevation is restricted direction.", "Correct. Upgaze fails from tethered inferior muscle.", "Incorrect. Medial wall traps medial rectus horizontally.", "Incorrect. Swelling diplopia differs and forced duction free."], "Cannot look up because muscle below is caught.")]);

add("ent-tonsils-adenoids", "Tonsils and adenoids", "tonsils_and_adenoids", "Tonsils and Adenoids",
 ["Recurrent tonsillitis", "Peritonsillar abscess quinsy", "Adenoid hypertrophy", "Tonsillectomy criteria"],
 [step("**Acute tonsillitis** is viral in most cases; bacterial (group A streptococcus) likelihood rises with Centor features: fever, tonsillar exudate, tender anterior cervical nodes and absence of cough (age adjusted McIsaac). Antibiotics (penicillin patterns) are for likely streptococcal, severe or high risk cases, preventing rheumatic fever in at risk populations, not shortening most viral illness. Infectious mononucleosis (EBV) mimics with fatigue, splenomegaly, atypical lymphocytes and amoxicillin rash, forbidding contact sports while spleen enlarged.", "Fever, pus, nodes, no cough scores strep. Mono plus amoxicillin erupts in rash; swollen spleen bans rugby."),
  step("**Peritonsillar abscess (quinsy)** collects between tonsil capsule and superior constrictor in young adults after tonsillitis: severe unilateral sore throat, trismus, drooling, muffled hot potato voice, uvula deviated away and bulging soft palate. Needle aspiration or incision drainage plus antibiotics and fluids treats most; airway vigilance precedes procedures, CT only for atypical, deep or paediatric concerns. Interval tonsillectomy debate follows recurrence and severity patterns individually.", "One sided agony, jaw locked, uvula pushed over: quinsy. Drain it, guard airway."),
  step("Recurrent tonsillitis surgery uses frequency thresholds (Paradise pattern: seven episodes in one year, five yearly for two years, or three yearly for three years, documented and disabling) balanced against natural resolution and surgical harms (bleeding about 2 to 5 percent spectrum, anaesthetic, pain). **Adenoid hypertrophy** obstructs growing children causing mouth breathing, hyponasal speech, snoring sleep apnoea, glue ear contribution and adenoid facies in chronicity; adenoidectomy indications centre obstruction and selected recurrent otitis or sinusitis pathways.", "Seven, five, three: Paradise counts for tonsillectomy. Big adenoids block noses, ears and sleep."),
  step("Tonsil cancer red flags rewrite sore throat care: unilateral tonsil enlargement or ulcer, referred otalgia (glossopharyngeal), neck mass, weight loss in adult smoker or drinker suggests squamous carcinoma (HPV positive oropharyngeal rising in younger non smokers with cystic level II node). Any persistent unilateral tonsil asymmetry in adult needs urgent cancer pathway examination and biopsy or tonsillectomy histology, never repeated antibiotics. Post tonsillectomy bleed returns to theatre when significant: primary under 24 hours (reactionary), secondary at 5 to 10 days (infection slough).", "One big ulcerated tonsil in adult is cancer until histology clears it. Day seven bleed after tonsillectomy returns urgently.", tbl(["Feature", "Quinsy", "Tonsillitis"], [["Laterality", "Unilateral severe", "Bilateral usual"], ["Trismus", "Present", "Absent"], ["Uvula", "Deviated away", "Midline"], ["Treatment", "Drainage plus antibiotics", "Supportive, selective antibiotics"]]))],
 ["Paradise criteria: 7 in 1 year, 5x2, 3x3", "Quinsy: trismus, uvula deviation, drainage", "Unilateral adult tonsil enlargement means cancer pathway", "Secondary post tonsillectomy bleed at 5 to 10 days"],
 "Streptococcal pharyngitis triggers immune sequelae in susceptible hosts, while peritonsillar spread breaches capsule planes; adenotonsillar lymphoid hypertrophy peaks physiologically in childhood narrowing airway relative to skeletal growth.",
 ["Quinsy versus peritonsillar cellulitis (pus proven by aspiration)", "Streptococcal versus EBV tonsillitis (rash, spleen, lymphocytes)", "Obstructive hypertrophy versus recurrent infection indications"],
 ["Centor scoring and rapid antigen or culture by local policy", "Aspiration yield for quinsy pus confirmation", "Sleep study when apnoea severity uncertain"],
 [mcq("bk2-ent-151", "Centor criteria comprise fever, exudate, tender anterior nodes and what fourth feature?", ["Cough present", "Absence of cough", "Hoarseness", "Conjunctivitis"], 1, "Absence of cough favours streptococcal over viral pharyngitis (cough, coryza, hoarseness point viral). Age modifies score in McIsaac version.", ["Incorrect. Cough argues viral.", "Correct. No cough is fourth Centor point.", "Incorrect. Hoarseness is viral clue.", "Incorrect. Conjunctivitis suggests viral or allergic."], "No cough scores for strep."),
  mcq("bk2-ent-152", "Young adult with trismus, drooling, hot potato voice and uvula pushed to opposite side most likely has what?", ["Bilateral tonsillitis", "Peritonsillar abscess", "Epiglottitis", "Dental abscess only"], 1, "Quinsy unilateral peritonsillar collection displaces uvula away, locks jaw via pterygoid irritation and muffles voice; drainage plus antibiotics is definitive. Epiglottitis stridors with tripod in children pattern.", ["Incorrect. Bilateral disease lacks deviation and trismus.", "Correct. Peritonsillar abscess quinsy.", "Incorrect. Epiglottitis airway signs dominate differently.", "Incorrect. Dental pain localises jaw teeth without uvula shift."], "Uvula pushed, jaw locked: drain quinsy."),
  mcq("bk2-ent-153", "Paradise tonsillectomy frequency pattern for recurrent tonsillitis is what?", ["3 in one year for all", "7 in 1 year, or 5 per year for 2 years, or 3 per year for 3 years documented", "Any sore throats counted by memory", "One quinsy always"], 1, "Documented disabling episodes meeting Paradise thresholds (with features like fever, nodes, exudate, treatment) justify surgery discussion; watchful waiting suits fewer episodes as many remit.", ["Incorrect. Three in one year insufficient alone.", "Correct. Seven, five by two, three by three.", "Incorrect. Documentation quality matters.", "Incorrect. Single quinsy is relative, debated indication."], "Seven five three unlocks tonsillectomy talk."),
  mcq("bk2-ent-154", "Amoxicillin rash in a fatigued teen with exudative tonsillitis, splenomegaly and atypical lymphocytosis indicates what?", ["Penicillin allergy lifelong label", "Infectious mononucleosis (EBV) rash interaction", "Scarlet fever", "Drug Stevens Johnson"], 1, "Aminopenicillins in acute EBV provoke morbilliform rash (not true allergy in most) with mono syndrome of fatigue, spleen and atypical lymphocytes; spleen rupture precautions and supportive care follow.", ["Incorrect. Rash here is virus drug interaction usually.", "Correct. EBV mononucleosis interaction.", "Incorrect. Scarlet has sandpaper rash and strawberry tongue strep pattern.", "Incorrect. No mucosal blistering syndrome."], "Mono plus amoxicillin equals rash, not allergy."),
  mcq("bk2-ent-155", "Secondary post tonsillectomy haemorrhage classically occurs when and from what?", ["Immediately in recovery only", "5 to 10 days from infection and slough separation", "One month later new vessels", "Never after discharge"], 1, "Secondary bleeding peaks five to ten days as fibrin slough separates with infection, ranging spit streaks to airway threatening haemorrhage needing urgent ENT return, resuscitation and often theatre arrest.", ["Incorrect. That is primary reactionary bleed under 24h.", "Correct. Day five to ten slough infection bleed.", "Incorrect. Late bleeds beyond are uncommon.", "Incorrect. Discharged patients are peak risk group."], "Day seven bleed returns to hospital fast."),
  mcq("bk2-ent-156", "Persistent unilateral tonsil enlargement with ulcer and referred ear pain in 60 year old smoker needs what?", ["Repeated antibiotic courses", "Urgent suspected cancer pathway: examination, imaging and tonsil histology or biopsy", "Reassure asymmetry normal", "Steroid gargle"], 1, "Oropharyngeal squamous carcinoma (and lymphoma) present asymmetrically with otalgia via glossopharyngeal referral and neck nodes; adults need two week wait style urgent assessment, never antibiotic loops.", ["Incorrect. Antibiotics delay cancer diagnosis.", "Correct. Urgent cancer pathway with histology.", "Incorrect. Adult asymmetry is red flag.", "Incorrect. Gargles mask malignancy."], "One angry tonsil in older adult: cancer pathway."),
  mcq("bk2-ent-157", "HPV positive oropharyngeal cancer increasingly presents in younger non smokers typically with what first sign?", ["Ulcerated huge tonsil always", "Cystic level II neck mass with small occult primary", "Hoarseness", "Dysphagia late only"], 1, "HPV driven tumours hide small tonsil or tongue base primaries while metastasising early to cystic level II nodes, with better treatment response than tobacco cancers; p16 testing guides pathway.", ["Incorrect. Primary often tiny and hidden.", "Correct. Cystic neck node, occult primary.", "Incorrect. Hoarseness is laryngeal site.", "Incorrect. Neck mass often precedes swallowing issues."], "Young neck cyst may be HPV cancer calling."),
  mcq("bk2-ent-158", "Adenoidectomy in children principally treats which problems?", ["Recurrent strep tonsillitis", "Nasal obstruction, sleep apnoea, selected glue ear and chronic adenoiditis sinusitis", "Epistaxis", "Laryngeal stridor"], 1, "Adenoids obstruct posterior nose and Eustachian region, so surgery targets obstructive sleep, mouth breathing and selected otitis or sinus pathways, often combined with tonsillectomy for sleep apnoea.", ["Incorrect. Tonsillectomy addresses tonsillitis.", "Correct. Obstruction, sleep and ear indications.", "Incorrect. Bleeding treated at vessel source.", "Incorrect. Stridor is laryngeal evaluation."], "Adenoids out for blockage, not sore throats."),
  mcq("bk2-ent-159", "Peritonsillar abscess drainage immediate priority before procedure is what?", ["CT for every case", "Airway assessment and readiness, since trismus and swelling can obstruct", "Interval tonsillectomy booking", "Steroids alone discharge"], 1, "Most quinsy drain awake with topical anaesthesia safely after airway evaluation, suction and positioning; CT reserves for deep neck suspicion, children, immunocompromise or failed aspiration. Airway deterioration changes to theatre plan.", ["Incorrect. Typical adult quinsy needs no CT.", "Correct. Airway readiness first.", "Incorrect. Booking follows acute resolution debate.", "Incorrect. Undrained pus needs procedure."], "Check airway before chasing pus."),
  mcq("bk2-ent-160", "Group A streptococcal pharyngitis treatment chiefly prevents which immune complication in at risk populations?", ["Post strep glomerulonephritis primarily", "Acute rheumatic fever (antibiotics proven); glomerulonephritis prevention unproven", "Scarlet fever rash", "Quinsy always"], 1, "Timely penicillin prevents rheumatic fever and suppurative spread; evidence does not show glomerulonephritis prevention. This drives treatment in high incidence populations more than symptom shortening.", ["Incorrect. PSGN not proven preventable by antibiotics.", "Correct. Rheumatic fever prevention is proven goal.", "Incorrect. Rash is toxin manifestation, not prevented target.", "Incorrect. Quinsy can still occur despite treatment occasionally."], "Penicillin guards the heart valves.")]);

add("ent-neck-spaces", "Deep neck space infections", "deep_neck_space_infections", "Deep Neck Space Infections",
 ["Ludwig angina", "Retropharyngeal abscess", "Parapharyngeal abscess", "Necrotising fasciitis neck"],
 [step("Deep neck infections spread along fascial planes from teeth (commonest), tonsils, salivary glands and foreign bodies, threatening airway, mediastinum, carotid and jugular structures. **Ludwig angina** is bilateral submandibular space cellulitis (usually odontogenic from lower molars) with woody floor of mouth, raised displaced tongue, drooling and airway obstruction risk, needing airway first (awake tracheostomy readiness), CT with contrast only when airway safe, broad antibiotics and surgical drainage with dental source removal.", "Woody mouth floor pushing tongue up is Ludwig angina: airway before scan, drain and pull the tooth."),
  step("**Retropharyngeal abscess** in young children (nodes draining nasopharynx, regressing by school age) causes fever, neck stiffness, torticollis, drooling and stridor mimicking epiglottitis or meningitis; adults get it from foreign body perforation, trauma or vertebral osteomyelitis spread. Parapharyngeal (lateral pharyngeal) abscess shows trismus, tonsil medial displacement and neck swelling, with carotid sheath posterior compartment risks: jugular thrombosis (Lemierre fusobacterial sepsis after pharyngitis in adolescents), carotid erosion blowout and lower cranial neuropathies.", "Stiff necked drooling toddler may have pus behind pharynx. Throat infection then septic jugular clot is Lemierre."),
  step("Imaging and airway sequencing rules care: unstable airway goes to theatre for controlled securing (fibreoptic or tracheostomy under local) before imaging trips; stable patients get contrast CT neck (and chest if mediastinitis suspected: widened mediastinum, chest pain, crepitus). Descending necrotising mediastinitis carries high mortality needing thoracic surgery drainage. Necrotising fasciitis (pain out of proportion, bullae, crepitus, rapid spread, diabetic hosts) demands immediate wide debridement beyond antibiotics.", "Secure airway first, then scan. Pus descending to chest needs chest surgeons too."),
  step("Complication vigilance continues after drainage: carotid blowout heralded by sentinel bleed, jugular thrombophlebitis septic emboli, mediastinitis, aspiration and sepsis. Source control (tooth extraction, foreign body removal, tonsil drainage pathways) plus cultures directed antibiotics (streptococci, anaerobes, staphylococci cover patterns) and HDU monitoring complete care. Diabetes and immunocompromise lower thresholds for imaging and surgery.", "Watch for warning bleeds from carotid after neck pus. Treating pus without removing tooth fails.", tbl(["Space", "Usual source", "Signature threat"], [["Submandibular (Ludwig)", "Lower molar teeth", "Tongue up, airway loss"], ["Retropharyngeal", "Child nodes, adult foreign body", "Stridor, mediastinum descent"], ["Parapharyngeal", "Tonsil, teeth", "Carotid sheath disasters"], ["Pretracheal", "Trauma, thyroiditis", "Mediastinitis direct"]]))],
 ["Ludwig angina is bilateral, dental, airway first", "Lemierre: Fusobacterium jugular thrombophlebitis after pharyngitis", "Descending mediastinitis needs thoracic drainage", "Sentinel bleed warns carotid blowout"],
 "Fascial planes guide pus predictably while venous drainage seeds internal jugular thrombophlebitis; floor of mouth swelling displaces tongue posteriorly against epiglottis in closed oral cavity.",
 ["Ludwig cellulitis versus abscess (drainage still often needed)", "Retropharyngeal abscess versus epiglottitis in child (neck stiffness, imaging)", "Lemierre versus simple tonsillitis by sepsis and neck pain timing"],
 ["Contrast CT neck and chest when airway stable", "Airway endoscopy assessment in theatre", "Blood cultures before antibiotics when safe"],
 [mcq("bk2-ent-161", "Bilateral woody submandibular swelling, floor of mouth raised, tongue pushed up, drooling after molar pain defines what?", ["Quinsy", "Ludwig angina", "Parotitis", "Ranula"], 1, "Ludwig angina is bilateral submandibular cellulitis (odontogenic) elevating tongue toward airway obstruction; it is primarily cellulitis though drainage and tooth removal plus airway control treat it.", ["Incorrect. Quinsy is unilateral peritonsillar.", "Correct. Ludwig angina floor of mouth emergency.", "Incorrect. Parotid swells cheek preauricular.", "Incorrect. Ranula is cystic floor swelling chronic."], "Woody mouth floor equals Ludwig airway alert."),
  mcq("bk2-ent-162", "First action in Ludwig angina with worsening drooling and voice change is what?", ["CT neck immediately alone", "Airway securing plan in theatre or ICU setting with ENT anaesthesia, anticipating tracheostomy", "Oral antibiotics discharge", "Incise in corridor"], 1, "Progressive floor swelling obstructs unpredictably; controlled airway (often awake fibreoptic or tracheostomy under local) precedes transport or drainage. Blind intubation attempts can lose airway.", ["Incorrect. Scanner trip without airway risks arrest.", "Correct. Secure airway in controlled setting first.", "Incorrect. Discharge unsafe.", "Incorrect. Drainage follows airway control."], "Airway before pictures in Ludwig."),
  mcq("bk2-ent-163", "Teenager recovers from sore throat then develops fever, lateral neck pain, rigors and lung septic emboli. Syndrome and organism?", ["Lemierre syndrome; Fusobacterium necrophorum jugular thrombophlebitis", "Quinsy; streptococcus", "Mono; EBV", "Lemierre; fungus"], 0, "Lemierre follows oropharyngeal infection (often Fusobacterium necrophorum) infecting internal jugular clot showering lungs; needs prolonged antibiotics, imaging and anticoagulation debate in specialist care.", ["Correct. Lemierre Fusobacterium jugular sepsis.", "Incorrect. Quinsy localises peritonsillar without emboli.", "Incorrect. EBV lacks septic emboli pattern.", "Incorrect. Fungus not classic agent."], "Sore throat, then neck, then lungs: Lemierre."),
  mcq("bk2-ent-164", "Retropharyngeal abscess in a 3 year old most closely mimics which conditions in presentation?", ["Croup only", "Epiglottitis and meningitis (fever, drooling, neck stiffness or extension avoidance)", "Asthma", "Foreign body only"], 1, "Prevertebral swelling causes fever, drooling, stridor and neck held stiff or extended, overlapping epiglottitis airway and meningitis stiffness; lateral neck imaging or CT after airway safety separates them.", ["Incorrect. Croup barks with steeple, less stiffness.", "Correct. Epiglottitis and meningitis mimicry.", "Incorrect. Asthma wheezes lower airway.", "Incorrect. Foreign body is one cause in adults pattern."], "Stiff drooling toddler: pus behind throat hides."),
  mcq("bk2-ent-165", "Small sentinel bleed from neck wound days after parapharyngeal abscess warns of what catastrophe?", ["Jugular thrombosis silent", "Carotid erosion impending blowout", "Salivary fistula", "Tracheitis"], 1, "Infected carotid sheath can erode arterial wall; herald bleeds precede exsanguinating blowout needing immediate theatre vascular control, airway and massive transfusion activation.", ["Incorrect. Jugular clot embolises, not sentinel bleed.", "Correct. Carotid blowout herald bleed.", "Incorrect. Fistula leaks saliva, not arterial warning.", "Incorrect. Tracheitis inflames airway without this sign."], "Warning bleed from infected neck: carotid next."),
  mcq("bk2-ent-166", "Descending necrotising mediastinitis from neck infection requires which team addition and why?", ["Dermatology; skin grafts", "Cardiothoracic surgery; mediastinal drainage beyond neck access", "Ophthalmology; eye checks", "Dental only"], 1, "Pus descending retropharyngeal or pretracheal planes into mediastinum cannot clear by neck incisions alone; thoracic drainage, broad sepsis care and repeat imaging drive survival.", ["Incorrect. Skin not central issue.", "Correct. Thoracic drainage needed.", "Incorrect. Eyes uninvolved pathway.", "Incorrect. Dental source removal necessary but insufficient."], "Neck pus in chest needs chest surgeons."),
  mcq("bk2-ent-167", "Pain out of proportion, bronze bullae, crepitus and rapid spread in diabetic neck infection indicate what until disproven?", ["Cellulitis simple", "Necrotising fasciitis needing immediate surgical debridement", "Allergy", "Salivary stone"], 1, "Necrotising soft tissue infection outruns antibiotics; early wide excision to healthy tissue with ICU and broad cover is life and airway saving, imaging must not delay theatre in classic signs.", ["Incorrect. Simple cellulitis lacks necrosis signs.", "Correct. Necrotising fasciitis, debride now.", "Incorrect. Allergy itches without crepitus pain.", "Incorrect. Stone obstructs gland mealtimes."], "Crepitus plus agony equals theatre, not observation."),
  mcq("bk2-ent-168", "Commonest source overall for deep neck space infections in adults is what?", ["Sinusitis", "Odontogenic (dental) infection", "Otitis", "Skin boils"], 1, "Lower molar roots below mylohyoid line seed submandibular and related spaces; dental imaging and extraction are source control without which antibiotics and drainage relapse.", ["Incorrect. Sinuses infect orbit and brain more.", "Correct. Teeth lead adult deep neck sepsis.", "Incorrect. Ear infects mastoid pathways.", "Incorrect. Skin is minority source."], "Adult neck pus: interrogate molars."),
  mcq("bk2-ent-169", "Stable airway child suspected retropharyngeal abscess: preferred imaging to confirm and plan?", ["No imaging, scope only", "Contrast CT neck (after airway assessment), lateral soft tissue film adjunct historically", "MRI spine only", "Ultrasound teeth"], 1, "CT defines retropharyngeal collection, mediastinal extent and drainage route in stable children; unstable airway bypasses imaging to theatre. Plain lateral widening supports but lacks surgical detail.", ["Incorrect. Confirmation and extent needed.", "Correct. Contrast CT when airway stable.", "Incorrect. Spine MRI suits vertebral cause later.", "Incorrect. Teeth ultrasound irrelevant."], "Stable: CT maps pus before drainage."),
  mcq("bk2-ent-170", "Ludwig angina microbiology and cover pattern typically target what?", ["Single aerobic virus", "Polymicrobial oral flora: streptococci plus anaerobes (staphylococci by setting)", "Pseudomonas only", "Fungi routinely"], 1, "Oral polymicrobial synergy drives cellulitis, so empirical regimens cover streptococci and anaerobes per local policy, narrowed by operative cultures, with MRSA additions by risk.", ["Incorrect. Viruses do not cause Ludwig.", "Correct. Mixed oral aerobes and anaerobes.", "Incorrect. Pseudomonas is ear canal pattern.", "Incorrect. Antifungals only immunocompromised proof."], "Mouth pus is mixed: cover anaerobes too.")]);

add("ent-nasopharynx", "Nasopharyngeal tumours", "nasopharyngeal_tumours", "Nasopharyngeal Tumours",
 ["Nasopharyngeal carcinoma", "EBV", "Serous otitis media adult", "Basal skull invasion"],
 [step("**Nasopharyngeal carcinoma** (NPC) arises most in fossa of Rosenmuller behind Eustachian orifice, strongly EBV associated, endemic in southern Chinese and Southeast Asian populations with genetic and salted fish nitrosamine links. It spreads early to retropharyngeal and level II or V nodes, often presenting as painless neck mass while primary stays silent. Histologies include non keratinising (EBV driven) and keratinising (smoking alcohol linked) types.", "Silent primary, loud neck nodes: NPC hides behind the Eustachian tube. EBV drives endemic type."),
  step("Symptoms map anatomy: unilateral serous otitis media from tube block (adult red flag), epistaxis or blood stained postnasal discharge, nasal obstruction, and cranial neuropathies when skull base invades (VI first causing diplopia, V pain or numbness, then IX to XII in jugular foramen extensions). Trotter triad historically: conductive deafness, trigeminal neuralgia type pain, palatal immobility ipsilateral. Examination needs nasendoscopy with biopsy of fossa lesions.", "One blocked ear, bloody postnasal drip, sixth nerve palsy: scope the nasopharynx. Trotter triad is exam heritage."),
  step("Workup: MRI nasopharynx and skull base (best soft tissue and perineural), CT bone base, EBV DNA plasma (screening and prognostic monitoring in endemic programmes), audiometry, staging PET CT for advanced nodes. Radiotherapy is primary treatment (nasopharynx surgically inaccessible), with concurrent chemotherapy for locoregionally advanced disease; intensity modulated techniques spare parotids and brain. Endemic screening with EBV serology or DNA shifts stage earlier.", "Radiation cures what surgery cannot reach. Plasma EBV DNA tracks this cancer."),
  step("Benign nasopharyngeal lesions include adenoid hypertrophy (children, rarely adults needing HIV or lymphoma exclusion when regrown), Thornwaldt cyst (midline nasopharyngeal cyst from notochord remnant, incidental or halitosis and discharge when infected), juvenile angiofibroma extension, and inverted papilloma or lymphoma mimics. Any adult nasopharyngeal mass with nodes gets malignancy pathway until histology, and unilateral effusion without mass still needs scope and imaging follow up.", "Adult adenoids regrown need a reason: lymphoma and immune deficiency enter list.", cmp("NPC presentation clues", ["Neck mass first from early lymphatic spread", "Unilateral adult glue ear from tube block", "Abducens palsy from skull base invasion"], "Why it matters", ["Primary stays silent while nodes declare", "Scope before any grommet in adults", "EBV DNA tracks tumour burden"]))],
 ["Adult unilateral glue ear equals scope nasopharynx", "NPC presents with neck nodes before nasal symptoms", "EBV DNA is biomarker for NPC", "Radiotherapy with chemotherapy is primary treatment"],
 "EBV latent proteins drive epithelial proliferation in genetically susceptible hosts primed by dietary nitrosamines, while submucosal growth silently invades skull base foramina and drains bilaterally to retropharyngeal nodes.",
 ["NPC versus lymphoma nasopharynx (histology decides)", "NPC ear effusion versus simple Eustachian dysfunction (scope finding)", "Thornwaldt cyst incidental versus tumour mass enhancement"],
 ["Nasendoscopy with targeted biopsy", "MRI skull base and neck, plasma EBV DNA", "PET CT staging in node positive disease"],
 [mcq("bk2-ent-171", "Commonest presentation of nasopharyngeal carcinoma is what?", ["Hoarseness", "Painless cervical lymph node mass (levels II and V)", "Stridor", "Toothache"], 1, "Rich submucosal lymphatics metastasise early (often bilaterally) while primary remains asymptomatic, so neck mass dominates presentations in endemic series. Posterior triangle level V nodes are classic.", ["Incorrect. Hoarseness is laryngeal.", "Correct. Neck nodes present first.", "Incorrect. Stridor is airway lesion.", "Incorrect. Dental pain is maxillary disease."], "Nodes shout, primary whispers: NPC."),
  mcq("bk2-ent-172", "Unilateral serous otitis media in a 50 year old from endemic region mandates what examination?", ["Audiogram discharge", "Nasopharyngeal endoscopy (with biopsy or imaging as found)", "Grommet immediate without inspection", "Ear drops"], 1, "Tumour at torus tubarius blocks tube causing effusion; inserting grommet without scoping misses NPC and can seed delay. Scope first, image and biopsy lesions.", ["Incorrect. Audiogram does not find cause.", "Correct. Scope nasopharynx first.", "Incorrect. Tube before scope is classic error.", "Incorrect. Drops cannot reach cause."], "Adult one sided glue ear: scope before tube."),
  mcq("bk2-ent-173", "First cranial nerve typically affected by skull base NPC invasion causing diplopia is which?", ["Optic II", "Abducens VI", "Facial VII", "Hypoglossal XII"], 1, "Long intracranial abducens course and Dorello canal vulnerability plus cavernous proximity make lateral gaze palsy earliest; lower cranial nerves follow jugular or hypoglossal canal extension later.", ["Incorrect. Vision falls with orbital apex late disease.", "Correct. Abducens VI first commonly.", "Incorrect. Facial nerve petrous route later.", "Incorrect. XII is late skull base sign."], "Sixth nerve falls first to skull base cancer."),
  mcq("bk2-ent-174", "Plasma biomarker used in NPC screening and monitoring is what?", ["PSA", "EBV DNA (quantitative)", "CEA", "CA 19 9"], 1, "Circulating EBV DNA mirrors tumour load, used in endemic population screening trials and post treatment surveillance for recurrence, alongside EBV serology (VCA IgA historical).", ["Incorrect. PSA is prostate.", "Correct. Plasma EBV DNA tracks NPC.", "Incorrect. CEA monitors colorectal.", "Incorrect. CA19 9 is pancreaticobiliary."], "EBV in blood betrays nasopharynx cancer."),
  mcq("bk2-ent-175", "Primary curative treatment for most NPC is what and why?", ["Radical nasopharyngectomy", "Radiotherapy (with concurrent chemotherapy if advanced) due surgical inaccessibility and radiosensitivity", "Chemotherapy alone all stages", "Observation"], 1, "Deep skull base location forbids clear surgical margins while tumour is radiosensitive; IMRT with concurrent cisplatin patterns for stage II onward improves survival, surgery salvages selected recurrences.", ["Incorrect. Anatomy prevents radical primary surgery.", "Correct. Radiation based primary cure.", "Incorrect. Chemo alone insufficient local cure.", "Incorrect. Cancer progresses untreated."], "Beam reaches where knife cannot: NPC."),
  mcq("bk2-ent-176", "Trotter triad in NPC classically comprises which three?", ["Deafness, trigeminal pain, palatal immobility ipsilateral", "Vertigo, tinnitus, facial palsy", "Anosmia, epistaxis, nodes", "Diplopia, proptosis, blindness"], 0, "Historical triad from lateral wall invasion: Eustachian conductive deafness, V3 distribution pain and soft palate paralysis (levator involvement), taught as skull base spread pattern.", ["Correct. Deaf ear, jaw pain, palate still.", "Incorrect. Those are ear neuroma features.", "Incorrect. Symptoms occur but not triad.", "Incorrect. Orbital invasion late differs."], "Ear, trigeminal, palate: Trotter three."),
  mcq("bk2-ent-177", "Midline smooth nasopharyngeal cyst found incidentally on MRI in adult is most likely what?", ["NPC", "Thornwaldt cyst (benign notochord remnant)", "Angiofibroma", "Encephalocele always"], 1, "Thornwaldt cyst sits midline posterior nasopharynx between longus muscles, usually incidental, occasionally infected causing halitosis and postnasal discharge treated by marsupialisation. Lateral fossa masses worry for tumour instead.", ["Incorrect. Cancer favours lateral fossa asymmetry.", "Correct. Midline Thornwaldt cyst benign.", "Incorrect. Angiofibroma lateral vascular teen mass.", "Incorrect. Encephalocele pulsatile with skull defect clues."], "Midline cyst is remnant, lateral mass is warning."),
  mcq("bk2-ent-178", "Regrown bulky adenoids in a 40 year old adult should prompt consideration of what besides chronic rhinitis?", ["Normal adult pattern", "Lymphoma and immunodeficiency (including HIV) evaluation", "Otosclerosis", "Pregnancy"], 1, "Adenoids involute after childhood; adult hypertrophy needs nasopharyngeal malignancy, lymphoma and immune suppression workup with biopsy, not assumption of allergy.", ["Incorrect. Adult regrowth is abnormal.", "Correct. Exclude lymphoma and immune causes.", "Incorrect. Ear bone disease unrelated.", "Incorrect. Not physiological cause."], "Adult adenoids demand a reason."),
  mcq("bk2-ent-179", "Endemic NPC strongest environmental and viral pairing is what?", ["HPV and oral sex pattern", "EBV plus genetic susceptibility and salted fish nitrosamines (southern Chinese populations)", "Asbestos and smoking", "EBV absent keratinising only"], 1, "Non keratinising endemic NPC integrates EBV latency with HLA genetics and early life nitrosamine diet; keratinising type in non endemic areas behaves more like other head neck squamous cancers.", ["Incorrect. HPV drives oropharyngeal tonsil cancer.", "Correct. EBV, genes and salted fish.", "Incorrect. Asbestos is mesothelial.", "Incorrect. EBV defines endemic biology."], "Virus plus genes plus salted fish equals endemic NPC."),
  mcq("bk2-ent-180", "MRI is preferred over CT for NPC staging chiefly because it best shows what?", ["Tooth roots", "Skull base invasion, perineural spread, retropharyngeal nodes and intracranial extent", "Bone only detail", "EBV level"], 1, "Soft tissue contrast defines submucosal primary, foraminal and cavernous invasion and node levels for radiation fields; CT complements cortical bone and EBV DNA quantifies burden separately.", ["Incorrect. CT dental bone wins there.", "Correct. Soft tissue and skull base spread.", "Incorrect. Bone is CT advantage.", "Incorrect. Blood test measures EBV."], "MRI maps soft invasion for the beam.")]);

add("ent-oral-hypopharynx-cancer", "Oral, oropharyngeal and hypopharyngeal cancers", "oral_oropharyngeal_hypopharyngeal_cancer", "Oral, Oropharyngeal and Hypopharyngeal Cancers",
 ["Oral cavity cancer", "HPV oropharyngeal", "Hypopharyngeal cancer", "Neck dissection"],
 [step("**Oral cavity cancer** (lip, tongue anterior two thirds, floor of mouth, buccal, palate, gingiva) is mostly squamous carcinoma driven by tobacco, alcohol synergy and betel or areca nut (submucous fibrosis), presenting as non healing ulcer over three weeks, red white patch (erythroplakia highest risk, leukoplakia), induration, loose tooth or referred otalgia. Oral tongue and floor metastasise early to levels I to III; depth of invasion now stages and drives elective neck treatment thresholds.", "Mouth ulcer three weeks is cancer until biopsy proves kind. Red patches outrank white for danger."),
  step("**Oropharyngeal cancer** split biologically: HPV positive (tonsil, tongue base, younger, cystic nodes, better prognosis, p16 marker) versus tobacco alcohol HPV negative (worse response). Hypopharyngeal cancer (pyriform sinus commonest subsite) presents latest and worst: dysphagia, odynophagia, referred otalgia, hoarseness from laryngeal invasion, weight loss and nodes, often with second primaries from field cancerisation of upper aerodigestive tract in smokers and drinkers (synchronous lung or oesophagus vigilance, panendoscopy traditions).", "HPV throat cancer answers treatment better. Pyriform sinus cancer arrives late and behaves worst."),
  step("Assessment maps primary (examination under anaesthesia, biopsy, p16), neck (ultrasound guided node sampling, CT or MRI, PET for advanced or unknown primary), distant spread (chest imaging) and host (nutrition, teeth, speech swallow, smoking alcohol cessation, anaesthetic). Unknown primary with squamous neck node triggers tonsillectomy and tongue base sampling pathways plus EBV and p16 testing to localise nasopharynx versus oropharynx origins.", "Node without primary: test p16 and EBV, take tonsils and tongue base samples."),
  step("Treatment is multidisciplinary by stage: early oral cancers surgery with margins and sentinel or elective neck dissection, reconstruction free flaps for tongue and floor defects; advanced or oropharyngeal often chemoradiation preserving organs, with surgery salvage. Hypopharynx frequently needs combined modality and laryngectomy decisions balancing voice. Dental clearance before radiation prevents osteoradionecrosis; speech, swallow and gastrostomy planning and smoking cessation change survival as much as modality choice.", "Cut early mouth cancers, beam many throat cancers, save voice where oncology allows. Teeth out before radiation or jaw bone dies.", tbl(["Subsite", "Driver clue", "Presentation anchor"], [["Oral tongue", "Tobacco, alcohol, betel", "Non healing lateral ulcer"], ["Oropharynx HPV+", "HPV16, p16 positive", "Cystic node, small primary, better prognosis"], ["Hypopharynx", "Heavy smoke and drink", "Late dysphagia, worst prognosis"], ["Lip", "Sunlight (lower lip)", "Crusting ulcer, best prognosis"]]))],
 ["Mouth ulcer over 3 weeks needs biopsy pathway", "Erythroplakia is highest risk premalignancy", "HPV positive throat cancer has better prognosis", "Hypopharyngeal cancer presents latest, fares worst"],
 "Field cancerisation bathes aerodigestive mucosa in carcinogens producing multifocal primaries, while HPV E6 E7 oncoproteins disable p53 and Rb in tonsillar crypt epithelium creating biologically distinct radiosensitive tumours.",
 ["Leukoplakia versus erythroplakia malignant risk", "HPV positive versus negative oropharynx by age, nodes, prognosis", "Hypopharynx versus oesophagus primary by endoscopy anatomy"],
 ["Biopsy and p16 immunohistochemistry, EBV where indicated", "CT or MRI primary and neck, PET CT advanced staging", "Dental, nutrition, speech swallow prehabilitation"],
 [mcq("bk2-ent-181", "Non healing mouth ulcer persisting beyond how long mandates urgent biopsy pathway?", ["3 days", "3 weeks", "3 months wait", "1 year"], 1, "Two to three week persistence thresholds (guidelines use three weeks for oral lesions, two week referral windows) separate traumatic ulcers healing in days from carcinoma or major aphthous mimics needing histology.", ["Incorrect. Days is normal healing window.", "Correct. Three weeks non healing biopsies.", "Incorrect. Months delay worsens stage.", "Incorrect. Year is negligent delay."], "Three weeks unhealed in mouth equals biopsy."),
  mcq("bk2-ent-182", "Which oral potentially malignant lesion carries highest transformation risk?", ["Homogeneous leukoplakia", "Erythroplakia (red patch)", "Frictional keratosis", "Geographic tongue"], 1, "Velvety red erythroplakia shows severe dysplasia or carcinoma in situ in majority at biopsy, far exceeding white leukoplakia risk; speckled red white lesions sit intermediate high.", ["Incorrect. White homogeneous lower risk.", "Correct. Red patch highest danger.", "Incorrect. Friction lesion resolves removing cause.", "Incorrect. Geographic tongue benign migratory."], "Red in mouth is danger: biopsy first."),
  mcq("bk2-ent-183", "Depth of invasion in oral tongue cancer chiefly drives which management decision beyond T staging?", ["Radiation dose only", "Elective neck dissection in node negative early cancers (occult metastasis risk)", "No neck treatment ever", "Chemotherapy for all thin"], 1, "Deeper invasion (thresholds around 4 mm patterns in guidelines) predicts occult nodal spread over 20 percent, justifying elective selective neck dissection or sentinel biopsy in clinically node negative early tongue and floor cancers.", ["Incorrect. Dose not primary depth use.", "Correct. Depth decides elective neck treatment.", "Incorrect. Observation risks occult nodes in deep lesions.", "Incorrect. Chemo not standard thin early."], "How deep decides whether silent neck gets treated."),
  mcq("bk2-ent-184", "p16 positive oropharyngeal cancer compared with HPV negative typically has which profile?", ["Older heavy smokers, poor response", "Younger, cystic nodes, better treatment response and prognosis", "No nodal spread", "Worse survival always"], 1, "HPV driven cancers in younger or non smoking patients metastasise to cystic nodes yet respond better to chemoradiation with superior survival, prompting de escalation research (not yet standard outside trials in many settings).", ["Incorrect. That is tobacco driven profile.", "Correct. Younger, cystic nodes, better prognosis.", "Incorrect. Nodes are hallmark early.", "Incorrect. Survival advantage is defining."], "HPV throat cancer: bad nodes, good outcome."),
  mcq("bk2-ent-185", "Worst prognosis major upper aerodigestive subsite among these is typically which?", ["Lip", "Hypopharynx (pyriform sinus)", "Early glottic", "HPV tonsil"], 1, "Hypopharyngeal cancers present with nodal and distant spread, malnutrition and second primaries, yielding lowest survival; lip and early glottic (sparse lymphatics, early hoarseness) fare best.", ["Incorrect. Lip sun cancers cure highly.", "Correct. Hypopharynx fares worst.", "Incorrect. Glottic declares early by voice.", "Incorrect. HPV tonsil prognosis favourable."], "Silent pyriform sinus kills most."),
  mcq("bk2-ent-186", "Squamous neck node with unknown primary: p16 positive points search where, EBV positive where?", ["p16 nasopharynx; EBV tonsil", "p16 oropharynx (tonsil, tongue base); EBV nasopharynx", "Both larynx", "Both skin"], 1, "Immunophenotyping directs occult search: HPV pathway to palatine and lingual tonsil sampling or tonsillectomy, EBV to nasopharyngeal biopsy, changing radiation fields and prognosis.", ["Incorrect. Reversed mapping.", "Correct. p16 oropharynx, EBV nasopharynx.", "Incorrect. Larynx usually declares by voice.", "Incorrect. Skin primary exam separate."], "p16 tonsil, EBV nasopharynx: stains point home."),
  mcq("bk2-ent-187", "Before head neck radiotherapy, dental intervention matters chiefly to prevent what?", ["Carries only", "Osteoradionecrosis from post radiation extractions in hypovascular bone", "Tooth whitening loss", "Dry mouth cure"], 1, "Radiation endarteritis makes mandible hypovascular; later extractions trigger non healing bone necrosis, so hopeless teeth are removed and fluoride trays instituted before treatment with healing interval.", ["Incorrect. Caries risk rises too but necrosis is catastrophe.", "Correct. Prevent osteoradionecrosis by pre radiation clearance.", "Incorrect. Cosmetic irrelevant.", "Incorrect. Xerostomia persists despite dental care."], "Bad teeth out before beam saves jaw."),
  mcq("bk2-ent-188", "Field cancerisation explains which phenomenon in smokers with hypopharyngeal cancer?", ["Single tumour only", "Synchronous and metachronous second primaries across lung, oesophagus and head neck", "Family inheritance", "Radiation effect"], 1, "Shared carcinogen exposure condemns whole mucosa, so staging and follow up survey second primaries (lung commonest lethal), and cessation remains survival intervention after diagnosis.", ["Incorrect. Multiplicity is point.", "Correct. Second primaries across aerodigestive field.", "Incorrect. Not germline pattern.", "Incorrect. Radiation second cancers are late different mechanism."], "Same smoke, many fields, many cancers."),
  mcq("bk2-ent-189", "Betel quid and areca nut chewing classically cause which premalignant oral condition restricting mouth opening?", ["Leukoplakia only", "Oral submucous fibrosis with blanching and trismus", "Geographic tongue", "Lichen planus only"], 1, "Areca alkaloids fibrose submucosa causing pale marble mucosa, burning spice intolerance and progressive trismus with high malignant transformation, prevalent in South and Southeast Asian chewers.", ["Incorrect. Leukoplakia is surface white patch separate.", "Correct. Submucous fibrosis stiffens mouth.", "Incorrect. Geographic tongue benign pattern.", "Incorrect. Lichen planus reticular immune condition."], "Betel mouth that cannot open: submucous fibrosis."),
  mcq("bk2-ent-190", "Referred otalgia from tongue or hypopharynx cancer travels via which shared sensory pathways chiefly?", ["Optic nerve", "Glossopharyngeal (IX) and vagus (X) auricular branches (Jacobson, Arnold)", "Facial motor", "Olfactory"], 1, "Ear and throat share IX and X sensory supply, so normal ear examination with persistent otalgia in adult demands oral, pharyngeal and laryngeal inspection for occult cancer or neuralgia causes.", ["Incorrect. Optic is vision.", "Correct. IX and X refer throat pain to ear.", "Incorrect. Facial motor moves face, taste separate.", "Incorrect. Smell nerve unrelated."], "Sore ear, clean ear: examine throat for cancer.")]);

add("ent-dysphagia", "Dysphagia and the oesophagus", "dysphagia_oesophagus_ent", "Dysphagia and the Oesophagus",
 ["Dysphagia oropharyngeal", "Oesophageal cancer dysphagia", "Achalasia", "Globus"],
 [step("**Dysphagia** separates into oropharyngeal (transfer failure: coughing, choking, nasal regurgitation, recurrent pneumonia, seconds after swallow attempt, from stroke, Parkinson, motor neuron and structural Zenker or cricopharyngeal causes) versus oesophageal (transit failure: food sticking retrosternally seconds later, solids versus liquids pattern). Solids only progressive suggests mechanical stricture or cancer; solids and liquids from start with regurgitation and weight loss suggests motility (achalasia, spasm). Intermittent solid impaction in young atopic man is eosinophilic oesophagitis until scoped.", "Chokes at once is throat transfer; sticks later is oesophagus. Solids only narrows; both phases fail movement."),
  step("Alarm features override functional labels at any age: progressive course, weight loss, anaemia, odynophagia, older onset, vomiting or family cancer need urgent endoscopy and imaging for malignancy (oesophageal adenocarcinoma on Barrett reflux rising, squamous from smoking alcohol). Rings (Schatzki), webs (Plummer Vinson iron deficiency with postcricoid web and cancer risk), strictures (reflux, caustic, radiation), extrinsic compression and candidiasis in immunocompromise (odynophagia dominant) fill benign differentials.", "Progressive sticking plus weight loss scopes urgently. Iron deficiency web at top is Plummer Vinson."),
  step("Oropharyngeal assessment uses speech therapy clinical swallow plus **videofluoroscopy** or FEES endoscopic evaluation defining aspiration (below cords, silent in neuro disease), penetration and which consistencies or manoeuvres are safe. Management treats cause, modifies textures (IDDSI levels), teaches chin tuck or Mendelsohn strategies, and decides oral versus gastrostomy feeding with patient goals; thickening reduces aspiration of thin fluids in selected patterns but does not suit all.", "Film the swallow to choose textures. Silent aspirators cough at nothing."),
  step("**Globus** is persistent lump in throat sensation between meals without dysphagia, odynophagia or weight loss, often reflux and hypervigilance related, diagnosed after normal examination and (when indicated) scope excluding lesions; reassurance with reflux measures and speech therapy tension release treats it. Zenker pharyngeal pouch (through Killian dehiscence in elderly) causes transfer dysphagia, regurgitation of undigested food, halitosis, gurgling neck swelling and aspiration, confirmed barium swallow, treated endoscopic stapling or open surgery, never blind NG tube or endoscopy force (perforation into pouch).", "Lump between meals without sticking is globus. Elderly regurgitated undigested food is Zenker pouch: barium first, tubes beware.", tbl(["Pattern", "Timing", "Likely level"], [["Cough, choke, nasal escape", "Immediate on swallow", "Oropharyngeal transfer"], ["Sticking behind sternum", "Seconds after", "Oesophageal body"], ["Solids only progressive", "Weeks months worsening", "Stricture or cancer"], ["Solids and liquids, regurgitation", "From onset", "Achalasia motility"]]))],
 ["Progressive solids dysphagia plus weight loss scopes urgently", "Zenker pouch: elderly, undigested regurgitation, barium diagnosis", "Globus has no true dysphagia or alarm features", "Plummer Vinson: iron deficiency plus postcricoid web"],
 "Failed upper sphincter relaxation or pharyngeal weakness leaves residue aspirating after swallow, while distal obstruction or absent peristalsis with non relaxing lower sphincter (achalasia myenteric loss) stagnates food above stomach.",
 ["Transfer versus transit dysphagia by immediate symptoms", "Achalasia bird beak versus cancer pseudoachalasia (age, short history)", "Globus versus dysphagia by meal relation"],
 ["Urgent gastroscopy with biopsies for alarm dysphagia", "Barium swallow for pouch and motility outline, manometry for achalasia", "Videofluoroscopy or FEES for oropharyngeal swallow"],
 [mcq("bk2-ent-191", "Dysphagia with immediate coughing, nasal regurgitation and recurrent pneumonias localises where?", ["Lower oesophagus", "Oropharyngeal transfer phase", "Stomach", "Colon"], 1, "Failure to protect airway and propel bolus from pharynx causes instant symptoms and aspiration pneumonia (stroke, Parkinson, MND), needing swallow filming and therapy, not primary oesophageal dilation.", ["Incorrect. Distal disease delays symptoms seconds.", "Correct. Oropharyngeal transfer failure.", "Incorrect. Gastric issues vomit and pain.", "Incorrect. Colon irrelevant to swallow."], "Chokes on first move: throat phase broken."),
  mcq("bk2-ent-192", "Progressive solids only dysphagia over 3 months with 8 kg loss in 65 year old smoker needs what urgently?", ["Reassurance globus", "Urgent upper GI endoscopy (cancer exclusion) with imaging pathway", "Speech therapy only", "Antacid year trial"], 1, "Alarm dysphagia (progressive mechanical pattern, weight loss, age) mandates urgent scope and biopsies for oesophageal or gastric cardia cancer, staging CT if confirmed. Functional labels are forbidden here.", ["Incorrect. Alarm forbids reassurance.", "Correct. Urgent endoscopy cancer pathway.", "Incorrect. Therapy follows exclusion.", "Incorrect. Acid trial delays diagnosis."], "Sticking plus shrinking equals scope now."),
  mcq("bk2-ent-193", "Dysphagia solids and liquids from onset, regurgitation and bird beak barium outline indicate what?", ["Cancer stricture", "Achalasia (failed lower sphincter relaxation, aperistalsis)", "Schatzki ring", "Web"], 1, "Achalasia loses myenteric neurons causing non relaxing lower sphincter and absent peristalsis; barium shows dilated oesophagus tapering beak, manometry confirms. Cancer pseudoachalasia mimics in older short history patients needing scope.", ["Incorrect. Cancer favours solids progressive shorter.", "Correct. Achalasia motility failure.", "Incorrect. Ring intermittently blocks solids (steakhouse).", "Incorrect. Web is high thin membrane solids only."], "Both phases blocked, beak below: achalasia."),
  mcq("bk2-ent-194", "Elderly man regurgitates undigested food hours later, halitosis and gurgling neck swelling suggest what and diagnostic test?", ["Achalasia; manometry", "Zenker pharyngeal pouch; barium swallow", "Globus; reassurance", "Oesophageal cancer; PET first"], 1, "Pharyngeal pouch through Killian dehiscence stores food causing delayed regurgitation, aspiration and Boerhaave risk with blind instrumentation; barium outlines it, endoscopic stapling divides common wall.", ["Incorrect. Achalasia retains in chest with dysphagia both.", "Correct. Zenker pouch on barium.", "Incorrect. Globus lacks regurgitation and swelling.", "Incorrect. Endoscopy first can perforate pouch."], "Old food returns undigested: Zenker pouch."),
  mcq("bk2-ent-195", "Iron deficiency anaemia, glossitis and postcricoid web causing dysphagia in middle aged woman is which syndrome?", ["Plummer Vinson (Paterson Brown Kelly)", "Achalasia cardia", "Barrett syndrome", "Mallory Weiss"], 0, "Plummer Vinson triad (iron deficiency, oesophageal webs, dysphagia) carries postcricoid carcinoma risk needing iron replacement, dilation and surveillance endoscopy.", ["Correct. Plummer Vinson web syndrome.", "Incorrect. Achalasia lacks iron web triad.", "Incorrect. Barrett is distal metaplasia reflux.", "Incorrect. Mallory Weiss tears bleed after retching."], "No iron, sore tongue, web: Plummer Vinson."),
  mcq("bk2-ent-196", "Young atopic man with intermittent solid food impaction (steakhouse episodes) and rings on endoscopy most likely has what?", ["Schatzki only in youth never", "Eosinophilic oesophagitis", "Achalasia", "Cancer"], 1, "Eosinophilic oesophagitis in allergic young males causes rings (trachealisation), furrows and strictures with food bolus arrests; biopsies (over 15 eosinophils per high power pattern) despite normal look, treated dietary elimination, topical swallowed steroids or PPIs pathways.", ["Incorrect. Schatzki is single mucosal ring older pattern.", "Correct. Eosinophilic oesophagitis of atopic youth.", "Incorrect. Liquids also fail in achalasia.", "Incorrect. Age and intermittence argue against."], "Atopic boy, steak stuck: eosinophils."),
  mcq("bk2-ent-197", "Silent aspiration means what and in whom is it classic worry?", ["Aspiration with violent cough in healthy", "Aspiration without cough or sensation, in neurological disease and post stroke or Parkinson", "Aspiration only asleep", "No pneumonia risk"], 1, "Lost laryngeal sensation lets material pass cords silently, so absence of coughing falsely reassures in neurogenic dysphagia; instrumental swallow studies (FEES, videofluoroscopy) reveal it guiding diet safety.", ["Incorrect. Violent cough is protective aspiration.", "Correct. Silent, neurologically blunted aspiration.", "Incorrect. Occurs awake eating classically.", "Incorrect. Pneumonia risk is high."], "No cough does not mean no aspiration."),
  mcq("bk2-ent-198", "Globus sensation is best defined how and managed after normal examination?", ["Food sticking with weight loss; scope yearly forever", "Lump feeling between meals without dysphagia or alarm, reassurance plus reflux and tension measures", "Painful swallow; antibiotics", "Regurgitation undigested; surgery"], 1, "Globus pharyngeus peaks between meals, swallowing food often eases it, and lacks alarm features; explanation, reflux lifestyle or therapy and laryngeal tension speech therapy settle most, investigating only red flags.", ["Incorrect. That is alarm dysphagia.", "Correct. Between meals lump, no alarm.", "Incorrect. Pain is odynophagia different problem.", "Incorrect. Regurgitation suggests pouch."], "Lump when not eating, eats fine: globus."),
  mcq("bk2-ent-199", "Painful swallowing (odynophagia) with white plaques in immunocompromised patient suggests what first?", ["Cancer only", "Candida oesophagitis (also HSV, CMV differentials)", "Achalasia", "Web"], 1, "Odynophagia dominant over dysphagia in HIV or steroid hosts points infective oesophagitis; candida commonest, endoscopy distinguishes viral ulcers when empiric fluconazole fails.", ["Incorrect. Cancer aches progressively with solids pattern.", "Correct. Candida infective oesophagitis.", "Incorrect. Achalasia regurgitates painlessly early.", "Incorrect. Webs block solids painlessly."], "Painful swallow plus immune down: candida."),
  mcq("bk2-ent-200", "Schatzki ring causes which classic episodic pattern?", ["Liquids dysphagia daily", "Intermittent solid (meat, bread) impaction at lower oesophageal mucosal ring, steakhouse syndrome", "Progressive weight loss", "Transfer choking"], 1, "A thin mucosal ring at squamocolumnar junction intermittently arrests poorly chewed meat boluses between long normal intervals, dilated at endoscopy after bolus clearance; eosinophilic disease must be biopsied in young.", ["Incorrect. Liquids pass rings freely.", "Correct. Episodic meat arrest, Schatzki ring.", "Incorrect. Weight stable between episodes.", "Incorrect. No pharyngeal transfer signs."], "Steak sticks yearly: Schatzki ring.")]);

add("ent-salivary", "Salivary gland disorders", "salivary_gland_disorders_ent", "Salivary Gland Disorders",
 ["Sialolithiasis", "Parotitis", "Pleomorphic adenoma", "Sjogren syndrome"],
 [step("Salivary glands (parotid serous, submandibular mixed, sublingual and minor glands) fail by obstruction, infection, autoimmunity and tumours. **Sialolithiasis** stones favour submandibular gland (80 percent pattern: alkaline mucinous saliva, uphill duct course) causing mealtime swelling and pain (salivary colic) easing between meals, with stone palpable in floor of mouth or seen on imaging; hydration, massage, sialagogues, duct dilation or sialendoscopy and gland excision escalate.", "Meal swells jaw, stone in submandibular duct. Parotid tumours and floor mouth stones live apart."),
  step("**Acute parotitis** divides bacterial (dehydrated elderly, post operative, Staphylococcus aureus, pus from Stensen duct, unilateral) from viral mumps (bilateral parotid swelling, orchitis, pancreatitis, meningitis associations, vaccine preventable). Chronic sialadenitis scar ducts after stones or radiation. **Sjogren syndrome** autoimmune lymphocytic destruction dries eyes and mouth (sicca, Schirmer test, anti Ro La, lip biopsy focus score), swelling parotids, risking lymphoma transformation needing vigilance for persistent hard enlargement.", "Dry eyes, dry mouth, swollen parotids: Sjogren. Hard persistent parotid in Sjogren hunts lymphoma."),
  step("Salivary **tumours**: parotid hosts most tumours and most are benign; smaller gland, higher malignancy share (sublingual and minor worst). **Pleomorphic adenoma** is commonest parotid tumour: slow painless preauricular mass, mixed epithelial myoepithelial histology, treated by superficial parotidectomy with facial nerve preservation (enucleation alone recurs from pseudopods), small long term malignant transformation risk in neglected masses. Mucoepidermoid carcinoma is commonest malignant salivary tumour overall; adenoid cystic creeps perineurally with pain and late lung metastases over decades.", "Big gland, benign odds; small gland, malignant odds. Pleomorphic adenoma comes out with cuff, never shelled."),
  step("Facial nerve and Frey syndrome frame parotid surgery: nerve trunk at stylomastoid foramen branches pes anserinus through gland (tumour deep or superficial to nerve defines operation), weakness after surgery usually temporary neuropraxia when preserved. **Frey syndrome** (gustatory sweating and flushing) follows auriculotemporal miswiring of parasympathetics to sweat glands, tested Minor starch iodine. Warthin tumour (older male smokers, bilateral parotid tail, cystic) is second benign pattern. Persistent parotid mass in adult needs imaging and fine needle sampling, never open incisional biopsy (seeding and nerve risk).", "Parotid surgery dances on facial nerve. Sweating while eating after parotidectomy is Frey rewiring.", tbl(["Gland", "Stone share", "Tumour malignancy share"], [["Submandibular", "Most stones (about 80 percent)", "Intermediate"], ["Parotid", "Fewer stones", "Mostly benign tumours"], ["Sublingual and minor", "Rare stones", "Mostly malignant proportion"], ["All glands", "Mealtime colic pattern", "Pleomorphic commonest benign"]]))],
 ["Submandibular gland grows most stones", "Pleomorphic adenoma: excise with margin, never enucleate", "Smaller gland tumour, higher cancer probability", "Frey syndrome is gustatory sweating after parotid surgery"],
 "Calcium rich stagnant saliva precipitates stones against gravity in Wharton duct, while autoimmune lymphoepithelial destruction and slow neoplastic growths with perineural affinity define tumour behaviours by gland site.",
 ["Bacterial versus viral parotitis by laterality and pus", "Pleomorphic adenoma versus Warthin by age, sex, bilaterality", "Sjogren swelling versus lymphoma transformation (persistent hard mass)"],
 ["Ultrasound first for stones and masses, sialendoscopy", "MRI parotid and fine needle aspiration for tumours", "Schirmer, anti Ro La and lip biopsy for Sjogren"],
 [mcq("bk2-ent-201", "Painful submandibular swelling surging at mealtimes and easing after most likely is what?", ["Parotid tumour", "Submandibular sialolithiasis (salivary colic)", "Ludwig angina", "Branchial cyst"], 1, "Stone obstructing Wharton duct backs saliva at secretory demand causing mealtime gland swelling; floor of mouth palpation and ultrasound find most stones. Tumours persist independent of meals.", ["Incorrect. Tumour mass is constant.", "Correct. Mealtime submandibular stone colic.", "Incorrect. Ludwig is woody bilateral emergency.", "Incorrect. Branchial cyst sits sternomastoid edge."], "Eats, swells, eases: duct stone."),
  mcq("bk2-ent-202", "Why does submandibular gland form most salivary stones?", ["It is smallest", "Alkaline mucin rich saliva flowing uphill against gravity in long duct", "It has no duct", "Viral predilection"], 1, "Wharton duct length, upward course, viscous calcium rich secretion predispose precipitation, unlike serous parotid flow downhill. Hence about four fifths of stones submandibular.", ["Incorrect. Size not cause.", "Correct. Uphill mucinous calcium flow stones.", "Incorrect. Long duct is itself factor.", "Incorrect. Viruses cause parotitis, not stones."], "Thick saliva uphill makes stones."),
  mcq("bk2-ent-203", "Commonest benign parotid tumour and its correct surgical principle is what?", ["Warthin; observe all", "Pleomorphic adenoma; superficial parotidectomy with facial nerve preservation, not enucleation", "Lipoma; shell out", "Haemangioma; embolise"], 1, "Pleomorphic adenoma pseudopods breach capsule, so enucleation seeds recurrence (and multinodular relapse endangers nerve later); formal superficial parotidectomy with nerve dissection is standard for superficial lobe tumours.", ["Incorrect. Warthin is second and selected observation debated.", "Correct. Pleomorphic adenoma, nerve sparing parotidectomy.", "Incorrect. Lipoma not commonest salivary tumour.", "Incorrect. Haemangioma is infant lesion different pathway."], "Never shell pleomorphic adenoma."),
  mcq("bk2-ent-204", "Sweating and flushing over cheek while eating months after parotidectomy is which syndrome and mechanism?", ["Horner syndrome", "Frey syndrome: parasympathetic fibres regrow to sweat glands", "First bite syndrome only", "Sjogren flare"], 1, "Auriculotemporal parasympathetics meant for parotid misdirect to cutaneous sweat glands and vessels (aberrant regeneration), so gustatory stimulus sweats skin; starch iodine test maps it, botulinum treats severe cases.", ["Incorrect. Horner is sympathetic eye signs.", "Correct. Frey gustatory sweating.", "Incorrect. First bite is pain with first mouthful after deep lobe or sympathetic injury.", "Incorrect. Sjogren dries glands systemically."], "Eats and cheek sweats: Frey rewiring."),
  mcq("bk2-ent-205", "Rule of thumb for salivary tumour malignancy probability by gland size is what?", ["Parotid most malignant", "Smaller the gland, greater proportion malignant (sublingual and minor highest)", "All glands equal", "Submandibular always benign"], 1, "Rough proportions invert with size: parotid about 20 percent malignant, submandibular near half, minor and sublingual majority malignant, so small gland masses biopsy urgently.", ["Incorrect. Parotid mostly benign.", "Correct. Small gland, sinister odds.", "Incorrect. Proportions differ markedly.", "Incorrect. Submandibular cancers common."], "Tiny gland lump, big cancer chance."),
  mcq("bk2-ent-206", "Commonest malignant salivary tumour overall, graded from low cystic to high solid, is what?", ["Adenoid cystic only", "Mucoepidermoid carcinoma", "Acinic cell only", "Squamous primary"], 1, "Mucoepidermoid carcinoma leads malignant salivary tumours (parotid especially), prognosis by grade; adenoid cystic is notorious perineural but second in frequency teaching.", ["Incorrect. Adenoid cystic second classic.", "Correct. Mucoepidermoid commonest malignant.", "Incorrect. Acinic less common.", "Incorrect. Primary squamous is uncommon diagnosis of exclusion."], "Mucoepidermoid tops malignant list."),
  mcq("bk2-ent-207", "Adenoid cystic carcinoma signature behaviour causing pain and very late recurrences is what?", ["Haematogenous only early", "Perineural invasion and indolent late lung metastases over decades", "Rapid nodal spread", "Hormone secretion"], 1, "Tumour tracks nerves causing pain and paraesthesia, skips nodes relatively, and metastasises to lungs after many years despite local control, needing lifelong follow up and generous nerve margin planning.", ["Incorrect. Early blood spread not signature.", "Correct. Perineural creep, decades late lungs.", "Incorrect. Nodes relatively spared.", "Incorrect. No secretory syndrome."], "Creeps nerves, returns in lungs at year fifteen."),
  mcq("bk2-ent-208", "Bilateral painful parotid swelling with fever in unvaccinated child plus orchitis in adolescent brother suggests what?", ["Bacterial parotitis", "Mumps (paramyxovirus)", "Sjogren", "Stones"], 1, "Mumps classically swells both parotids (one may lead) with systemic features and extrasalivary orchitis, pancreatitis or meningitis; bacterial parotitis is unilateral pus in dehydrated elderly.", ["Incorrect. Bacterial is unilateral elderly pus.", "Correct. Mumps bilateral viral pattern.", "Incorrect. Sjogren chronic dry autoimmune adult.", "Incorrect. Stones colic with meals unilateral."], "Both parotids plus orchitis equals mumps."),
  mcq("bk2-ent-209", "Persistent hard unilateral parotid enlargement developing in longstanding Sjogren patient raises concern for what?", ["Stone formation only", "MALT lymphoma transformation", "Frey syndrome", "Warthin always"], 1, "Chronic B cell stimulation in Sjogren multiplies lymphoma risk (MALT type in parotid), so new persistent, hard or rapidly enlarging gland, nodes or B symptoms need biopsy pathway.", ["Incorrect. Stones colic intermittently, not hard growth.", "Correct. Lymphoma transformation vigilance.", "Incorrect. Frey is post surgical sweating.", "Incorrect. Warthin is smoker older male pattern separate."], "Sjogren gland turning hard: biopsy for lymphoma."),
  mcq("bk2-ent-210", "Second commonest benign parotid tumour in older male smokers, often bilateral at parotid tail, is what?", ["Pleomorphic adenoma", "Warthin tumour (adenolymphoma)", "Oncocytoma rare", "Basal cell adenoma"], 1, "Warthin tumour (papillary cystadenoma lymphomatosum) associates smoking, older men, parotid tail cystic masses and bilaterality about a tenth, with very low malignant change.", ["Incorrect. Pleomorphic is first commonest, solitary female tilt.", "Correct. Warthin of older male smokers.", "Incorrect. Oncocytoma rarer.", "Incorrect. Basal adenoma less classic vignette."], "Smoking grandfather, tail cysts both sides: Warthin.")]);

add("ent-stridor-paediatric", "Stridor and congenital laryngeal lesions", "stridor_congenital_laryngeal", "Stridor and Congenital Laryngeal Lesions",
 ["Laryngomalacia", "Croup laryngotracheitis", "Epiglottitis", "Laryngeal papillomatosis"],
 [step("**Stridor** is harsh high pitched sound from laryngeal or tracheal obstruction (above carina), distinct from stertor (nasopharyngeal snoring rattle) and wheeze (lower airway musical). Inspiratory stridor localises supraglottis or glottis, biphasic to fixed glottic or subglottic lesions, expiratory to intrathoracic trachea. Any child with stridor gets airway first assessment: position of comfort, oxygen, no throat inspection or separation distress in suspected epiglottitis until theatre airway team assembled.", "Stridor sings from voice box; stertor snores from nose throat; wheeze whistles from chest. Do not poke epiglottitis throats."),
  step("**Laryngomalacia** is commonest congenital stridor: floppy supraglottic structures (omega epiglottis, short aryepiglottic folds, prolapsing arytenoids) sucked in on inspiration from first weeks, worse feeding, supine or agitated, better prone, usually self resolving by 18 to 24 months as cartilage stiffens. Severe cases with failure to thrive, apnoea or respiratory distress need supraglottoplasty. Reflux aggravates airway oedema and is co treated.", "Newborn inspiratory noise better prone is laryngomalacia. Most outgrow floppy voice box by age two."),
  step("Acute stridor emergencies separate by story: viral **croup** (laryngotracheitis, 6 months to 6 years, barking seal cough, steeple subglottic narrowing, night onset, steroids and nebulised adrenaline) versus bacterial **epiglottitis** (unimmunised toddler, toxic, drooling, tripod, thumbprint epiglottis, theatre intubation, Hib) versus inhaled foreign body (sudden choking in toddler, unilateral signs, rigid bronchoscopy), bacterial tracheitis (toxic, croup like but adrenaline unresponsive, purulent airway), anaphylaxis and retropharyngeal abscess.", "Barking night cough is croup. Drooling tripod toxic child is epiglottitis: theatre, tube, no tongue depressor.", tbl(["Cause", "Child clue", "Airway action"], [["Laryngomalacia", "Infant weeks old, better prone", "Reassure, operate severe only"], ["Croup", "Bark at night, low fever", "Steroid, adrenaline if severe"], ["Epiglottitis", "Toxic, drools, tripod", "Theatre intubation, antibiotics"], ["Foreign body", "Sudden choke playing", "Rigid bronchoscopy removal"]])) ,
  step("Other congenital lesions present in infancy: **subglottic haemangioma** (stridor from about six weeks, cutaneous beard haemangiomas in half, propranolol responsive), laryngeal webs and atresia (aphonia or distress at birth), vocal cord palsy and tracheo oesophageal anomalies with feeding aspiration. Flexible endoscopy in theatre with anaesthesia grades lesions (Cotton Meyer subglottic scale) guiding observation, medical therapy or airway surgery, while tracheostomy remains rescue for severe fixed obstruction.", "Birth airway lesions range webs to haemangiomas. Scope grades them; propranolol shrinks subglottic haemangioma.")],
 ["Laryngomalacia is commonest congenital stridor", "Croup barks with steeple; epiglottitis drools with thumbprint", "No throat examination in suspected epiglottitis", "Foreign body is sudden stridor in well toddler"],
 "Immature supraglottic cartilage collapses under inspiratory negative pressure (Venturi) in laryngomalacia, while viral subglottic oedema in fixed cricoid ring (narrowest paediatric segment historically funnel) amplifies croup obstruction.",
 ["Croup versus epiglottitis by toxicity, drool and cough", "Laryngomalacia versus vocal cord palsy (cry quality, birth or cardiac surgery)", "Stridor versus wheeze by sound and phase"],
 ["Flexible nasendoscopy awake in stable stridor", "Neck imaging only when airway safe (steeple, thumbprint adjuncts)", "Rigid bronchoscopy for foreign body and airway diagnosis"],
 [mcq("bk2-ent-211", "Commonest cause of congenital stridor beginning in first weeks, worse supine, better prone, is what?", ["Subglottic stenosis", "Laryngomalacia", "Vocal cord palsy", "Tracheomalacia only"], 1, "Supraglottic floppiness prolapses on inspiration in neonates, feeding or reflux aggravated, resolving as airway matures by about two years in most. Cord palsy weakens cry with aspiration pattern instead.", ["Incorrect. Stenosis is fixed biphasic noise after intubation often.", "Correct. Laryngomalacia leads congenital stridor.", "Incorrect. Palsy alters cry quality.", "Incorrect. Tracheomalacia expiratory bark pattern."], "Floppy newborn voice box: laryngomalacia."),
  mcq("bk2-ent-212", "Three year old at midnight with seal bark cough, stridor, low grade fever, responds to steroid. Diagnosis and airway X ray sign?", ["Epiglottitis; thumbprint", "Viral croup (laryngotracheitis); steeple sign subglottic narrowing", "Foreign body; air trapping", "Asthma; hyperinflation"], 1, "Parainfluenza croup oedematises subglottis (steeple on AP neck film, imaging rarely needed) causing bark and stridor; dexamethasone reduces severity and returns, adrenaline buys time in severe obstruction.", ["Incorrect. Epiglottitis drools toxic without bark.", "Correct. Croup with steeple sign.", "Incorrect. Foreign body sudden afebrile choking.", "Incorrect. Asthma wheezes expiratory."], "Midnight bark, steeple neck: croup."),
  mcq("bk2-ent-213", "Toxic drooling 4 year old sitting forward, thumbprint epiglottis suspected. Immediate rule is what?", ["Tongue depressor examination", "Do not instrument throat; assemble ENT anaesthesia in theatre for controlled intubation", "Oral antibiotics home", "Nebuliser trial on ward alone"], 1, "Epiglottic swelling can completely obstruct with distress or instrumentation; child stays with parent, minimal upset, theatre team secures airway under inhalational anaesthesia with surgical backup, then IV antibiotics (Hib cover patterns).", ["Incorrect. Depressor can close airway.", "Correct. Theatre controlled airway, hands off throat.", "Incorrect. Home care risks death.", "Incorrect. Ward nebuliser delays definitive airway."], "Drooling tripod: theatre tube, no peeking."),
  mcq("bk2-ent-214", "Nebulised adrenaline in severe croup provides what benefit and limitation?", ["Cures virus", "Temporary (about 2 hours) obstruction relief, needs steroid cover and observation for rebound", "Permanent cure", "Replaces airway team in epiglottitis"], 1, "Vasoconstriction shrinks subglottic oedema briefly (onset minutes, waning by two hours) bridging steroid effect; discharge waits observation after last dose per local policy. It never secures epiglottitis airway.", ["Incorrect. Symptomatic, not antiviral.", "Correct. Two hour bridge with steroid.", "Incorrect. Effect fades.", "Incorrect. Epiglottitis needs intubation."], "Adrenaline buys two hours in croup."),
  mcq("bk2-ent-215", "Sudden stridor and unilateral reduced air entry after toddler choked on peanut at party needs what?", ["Inhaler trial weeks", "Rigid bronchoscopy for inhaled foreign body removal", "Reassure as croup", "Heimlich if asymptomatic now"], 1, "Organic foreign bodies (peanut oils inflame) lodge bronchus (right more vertical) or larynx causing ball valve signs; bronchoscopy diagnoses and removes, imaging may show air trapping but normal film does not exclude.", ["Incorrect. Delay infects and swells object.", "Correct. Rigid bronchoscopy removal.", "Incorrect. Afebrile sudden onset not croup.", "Incorrect. Asymptomatic intervals still harbour object."], "Choked toddler, one quiet lung: scope it out."),
  mcq("bk2-ent-216", "Bilateral vocal cord palsy in neonate most characteristically presents how and associates with what?", ["Barking cough only", "Stridor with weak cry and aspiration, central causes like Chiari malformation or birth injury", "Noisy only feeding", "Hoarseness in teen"], 1, "Both cords near midline obstruct airway (stridor, possible tracheostomy) while unilateral palsy weakens cry and aspirates; bilateral neonatal cases need brain and Chiari evaluation (Arnold Chiari II with myelomeningocele classic).", ["Incorrect. Bark is subglottic croup.", "Correct. Bilateral palsy stridor, central hunt.", "Incorrect. Feeding noise alone is malacia pattern.", "Incorrect. Teen hoarseness is functional or papilloma."], "Both cords frozen in baby: check brain stem causes."),
  mcq("bk2-ent-217", "Unilateral vocal cord palsy after thyroidectomy in adult mainly causes what?", ["Stridor emergency always", "Breathy hoarseness, weak cough and aspiration risk, usually airway adequate", "Complete aphonia always", "No symptoms"], 1, "One paramedian cord leaves glottic gap wasting air and protection; speech therapy, temporary injection medialisation or thyroplasty restores voice and swallow, while bilateral palsy threatens airway instead.", ["Incorrect. Single cord rarely obstructs.", "Correct. Breathy voice and aspiration.", "Incorrect. Whispered voice remains.", "Incorrect. Voice change is defining."], "One cord out: breathy. Two out: airway."),
  mcq("bk2-ent-218", "Recurrent respiratory papillomatosis causing progressive hoarseness and stridor in child is driven by which virus and birth link?", ["EBV", "HPV 6 and 11, often vertical exposure at vaginal delivery in juvenile onset", "Parainfluenza", "RSV"], 1, "Low risk HPV types grow exophytic laryngeal papillomas needing repeated surgical debulking preserving voice, adjuvant therapies in aggressive disease, HPV vaccination prevention shifting epidemiology.", ["Incorrect. EBV drives nasopharynx and mono.", "Correct. HPV 6 and 11 papillomas.", "Incorrect. Parainfluenza causes croup acutely.", "Incorrect. RSV bronchiolitis lower airway."], "Warty voice box in child: HPV six eleven."),
  mcq("bk2-ent-219", "Subglottic stenosis in child is most often acquired from what and sounds how?", ["Birth weight only", "Prolonged neonatal intubation injury; fixed biphasic stridor", "Reflux only", "Measles"], 1, "Cricoid subglottis is narrowest fixed ring; endotracheal pressure scars it circumferentially causing biphasic noise and croup that fails to resolve, graded Cotton Meyer for airway surgery decisions.", ["Incorrect. Weight not mechanism.", "Correct. Intubation scar, biphasic fixed stridor.", "Incorrect. Reflux aggravates, rarely sole cause.", "Incorrect. Measles caused historical croup deaths, not stenosis pattern."], "Tube scar at cricoid narrows both breath phases."),
  mcq("bk2-ent-220", "Steeple sign versus thumbprint sign on neck imaging belong to which pair in order?", ["Epiglottitis, croup", "Croup subglottic steeple; epiglottitis swollen epiglottis thumbprint", "Foreign body, tumour", "Normal variants"], 1, "AP film in croup tapers subglottis to steeple (church spire), lateral film in epiglottitis shows thumb sized epiglottis; imaging never delays airway care in unstable children.", ["Incorrect. Reversed pairing.", "Correct. Steeple croup, thumbprint epiglottitis.", "Incorrect. Those lack these signs.", "Incorrect. Both pathological."], "Steeple barks, thumbprint drools.")]);

add("ent-vocal-cord-palsy", "Vocal cord paralysis", "vocal_cord_paralysis_ent", "Vocal Cord Paralysis",
 ["Recurrent laryngeal nerve", "Vocal cord palsy causes", "Thyroplasty", "Bilateral cord palsy airway"],
 [step("The **recurrent laryngeal nerve** supplies all intrinsic laryngeal muscles except cricothyroid (external superior laryngeal nerve), with asymmetric course: right loops subclavian artery, left loops aortic arch through thorax, making left palsy commoner from lung, aortic and mediastinal disease. Vagus lesions high add palate and pharynx signs; superior laryngeal injury (thyroid surgery) loses pitch range and projection (singers) via cricothyroid tension failure and supraglottic sensation (internal branch) aspiration.", "Left cord nerve tours chest, so left palsies hunt lungs. Pitch loss after thyroid surgery is superior nerve, not recurrent."),
  step("Causes by segment: skull base and jugular foramen syndromes, neck surgery (thyroid, carotid, cervical spine anterior approach), malignancy (lung apex Pancoast, thyroid, oesophagus), aortic aneurysm (Ortner cardiovocal syndrome: left palsy from enlarged left atrium or aorta), intubation trauma (arytenoid dislocation mimics palsy but is mechanical), viral idiopathic (post viral neuritis pattern) and central strokes. Any unexplained palsy images nerve course from skull base to aortopulmonary window (CT contrast).", "No cause given for palsy: scan from skull base to chest window. Big heart can silence left cord (Ortner)."),
  step("Examination: flexible laryngoscopy shows paramedian or lateral (cadaveric in high vagal) cord position, bowing, pooled secretions and aspiration; stroboscopy grades vibration for voice work. Unilateral palsy voices breathy, diplophonic, fatigues, coughs weakly and aspirates thin fluids. Management: speech therapy first, early temporary injection medialisation (months resorbing gels) when aspiration or professional voice demands, permanent medialisation thyroplasty or arytenoid adduction after recovery window (about 9 to 12 months for neurapraxia), reinnervation in selected young patients.", "Inject early for swallow safety, frame surgery after a year if nerve stays dead."),
  step("**Bilateral palsy** is airway disease: cords rest near midline (recurrent nerves, abductor posterior cricoarytenoid only opener fails) causing inspiratory stridor with surprisingly preserved voice, after thyroid surgery, malignancy or neurological disease. Tracheostomy secures severe obstruction; later cordotomy, arytenoidectomy or lateralisation trades voice quality for airway. Bilateral paralysis with stridor must never be sedated or scoped casually without airway plan.", "Two midline cords whisper well but breathe badly. Airway surgery buys breath with voice currency.", tbl(["Lesion","Cord position effect","Dominant problem"], [["Unilateral recurrent", "Paramedian one side", "Breathy voice, aspiration"], ["Bilateral recurrent", "Both near midline", "Stridor airway obstruction"], ["High vagal", "Cadaveric lateral plus palate signs", "Severe dysphagia and voice"], ["Superior laryngeal external", "Cricothyroid fails", "Pitch range and projection loss"]]))],
 ["Left recurrent nerve longer: left palsy commoner", "Image skull base to aortopulmonary window in idiopathic palsy", "Ortner syndrome is cardiac left cord palsy", "Bilateral palsy: voice okay, airway threatened"],
 "Posterior cricoarytenoid sole abductor failure closes glottis in bilateral recurrent lesions, while high vagal injury adds pharyngeal and palatal paralysis compounding aspiration beyond cord gap.",
 ["Arytenoid dislocation versus nerve palsy (trauma, palpation mobility)", "Unilateral versus bilateral palsy priorities (voice versus airway)", "Superior versus recurrent laryngeal injury after thyroidectomy"],
 ["Flexible laryngoscopy with stroboscopy", "CT skull base to mediastinum for unexplained palsy", "Swallow assessment (FEES) for aspiration grading"],
 [mcq("bk2-ent-221", "Left vocal cord palsy is commoner than right chiefly because what?", ["Left nerve shorter", "Left recurrent nerve loops aortic arch with long thoracic course exposed to lung and mediastinal disease", "Right nerve absent", "Left cord larger"], 1, "Intrathoracic left course past aortopulmonary window exposes nerve to bronchogenic cancer, aneurysm and mediastinal nodes; right loops higher at subclavian. Imaging must cover chest window.", ["Incorrect. Left is longer.", "Correct. Long thoracic left course vulnerable.", "Incorrect. Right nerve exists, loops subclavian.", "Incorrect. Cord size symmetric."], "Left nerve tours chest and meets cancer."),
  mcq("bk2-ent-222", "Ortner (cardiovocal) syndrome is vocal palsy caused by what?", ["Thyroid cancer always", "Cardiovascular enlargement (left atrium in mitral stenosis classically, aortic aneurysm) compressing left recurrent nerve", "Viral neuritis", "Intubation"], 1, "Enlarged left atrium or dilated aorta in aortopulmonary window compresses recurrent nerve causing hoarseness in cardiac disease, described with severe mitral stenosis; modern cases include aneurysm and pulmonary hypertension.", ["Incorrect. Cancer separate cause.", "Correct. Heart and aorta squeeze nerve.", "Incorrect. Viral is idiopathic diagnosis of exclusion.", "Incorrect. Tube trauma is arytenoid or nerve injury acute."], "Big heart, weak voice: Ortner."),
  mcq("bk2-ent-223", "Singer after thyroidectomy cannot reach high notes or project, cords mobile. Which nerve injured?", ["Recurrent laryngeal", "External branch superior laryngeal (cricothyroid motor)", "Hypoglossal", "Spinal accessory"], 1, "Cricothyroid tenses cord for pitch; external superior laryngeal branch runs on inferior constrictor near superior thyroid vessels at risk in thyroid surgery, subtle on routine scope without stroboscopy or pitch testing.", ["Incorrect. Recurrent injury immobilises cord visibly.", "Correct. Superior external branch pitch loss.", "Incorrect. Hypoglossal moves tongue.", "Incorrect. Accessory shrugs shoulder."], "Mobile cords, lost top notes: superior nerve."),
  mcq("bk2-ent-224", "Unexplained unilateral cord palsy workup imaging span is what?", ["Larynx only", "Skull base through neck to aortopulmonary window chest (CT contrast pattern)", "Brain only", "Sinuses only"], 1, "Entire vagus and recurrent course must be surveyed for tumours and vascular lesions from jugular foramen to mediastinum; limited laryngeal views miss lung apex and skull base causes.", ["Incorrect. Larynx shows effect, not cause.", "Correct. Skull base to chest window scan.", "Incorrect. Brain misses thoracic nerve.", "Incorrect. Sinuses irrelevant pathway."], "Follow nerve whole journey on scan."),
  mcq("bk2-ent-225", "Early injection medialisation in unilateral palsy is prioritised most when which problem dominates?", ["Cosmetic neck", "Aspiration with pneumonia risk or urgent professional voice need", "Mild huskiness weekends", "Bilateral stridor"], 1, "Temporary gels close glottic gap improving cough, swallow safety and voice while nerve recovery declares; bilateral airway cases instead need obstruction relief, not medialisation.", ["Incorrect. Neck appearance not indication.", "Correct. Aspiration or voice urgency injects early.", "Incorrect. Mild cases start speech therapy.", "Incorrect. Medialising obstructed airway worsens it."], "Choking on water: push cord midline early."),
  mcq("bk2-ent-226", "Bilateral cord palsy after thyroid surgery presents most characteristically how?", ["Aphonia with no stridor", "Inspiratory stridor with relatively preserved voice, airway emergency potential", "Barking cough", "Only aspiration silent"], 1, "Paramedian cords narrow airway while voicing near normally (cords meet), surprising juniors; stridor at extubation may need reintubation or tracheostomy, later lateralisation procedures balance breath and voice.", ["Incorrect. Voice often serviceable.", "Correct. Stridor dominates, voice deceives.", "Incorrect. Bark is child subglottis.", "Incorrect. Aspiration occurs but airway leads."], "Speaks fine, breathes terribly: both cords."),
  mcq("bk2-ent-227", "Immobile cord after difficult intubation with arytenoid asymmetry and normal nerve studies suggests what instead of palsy?", ["Idiopathic palsy", "Arytenoid dislocation (mechanical), needing reduction or therapy", "Lung cancer", "Superior nerve injury"], 1, "Tube pressure can sublux cricoarytenoid joint mimicking paralysis; CT joint asymmetry and palpation under anaesthesia distinguish, early reduction restores motion unlike wait and watch neuropathy.", ["Incorrect. Trauma timing points mechanical.", "Correct. Dislocated arytenoid mimics palsy.", "Incorrect. Cancer lacks intubation link.", "Incorrect. Superior injury keeps cord mobile."], "Stuck joint, live nerve: arytenoid dislocation."),
  mcq("bk2-ent-228", "High vagal lesion above superior laryngeal branch adds which signs to cord palsy?", ["Pitch loss only", "Palatal weakness, pharyngeal anaesthesia, severe dysphagia (cadaveric cord)", "Shoulder drop", "Tongue wasting only"], 1, "Jugular foramen level vagus failure paralyses palate and pharynx with cord lateral cadaveric position (all branches lost), devastating swallow beyond isolated recurrent lesions; accessory and hypoglossal neighbours may join (syndromes).", ["Incorrect. Pitch is superior branch isolated.", "Correct. Palate and pharynx join high lesions.", "Incorrect. Shoulder is accessory XI separate (may coexist).", "Incorrect. Tongue is XII separate."], "High vagus takes palate and throat too."),
  mcq("bk2-ent-229", "Permanent medialisation thyroplasty is generally timed when and why?", ["Immediately day one all", "After 9 to 12 months without recovery (or when prognosis hopeless earlier), implant adjusts cord position awake with voice feedback", "Never in elderly", "Before speech therapy trial always"], 1, "Waiting allows neurapraxia recovery while temporary injections bridge; frame implant (Isshiki type I) placed under local anaesthesia tuning voice live. Cancer invasion cases may proceed sooner by prognosis.", ["Incorrect. Early permanence overtreats recoverable nerves.", "Correct. Wait recovery window, tune awake.", "Incorrect. Elderly benefit well.", "Incorrect. Therapy precedes or accompanies."], "Give nerve a year, then frame the cord."),
  mcq("bk2-ent-230", "Posterior cricoarytenoid muscle unique role explaining bilateral palsy obstruction is what?", ["Only adductor", "Sole abductor opening glottis; its failure leaves cords midline", "Tenses cord for pitch", "Closes upper sphincter"], 1, "All other intrinsic muscles adduct or tense; posterior cricoarytenoid alone abducts, so bilateral recurrent failure unopposed adduction narrows airway at glottis despite intact voice closure.", ["Incorrect. Adductors are several other muscles.", "Correct. Sole opener fails closed.", "Incorrect. Cricothyroid tenses.", "Incorrect. Sphincter is oesophageal inlet."], "One opener muscle: lose both sides, lose airway.")]);

add("ent-laryngeal-cancer", "Carcinoma of the larynx", "laryngeal_carcinoma", "Carcinoma of the Larynx",
 ["Glottic cancer", "Supraglottic cancer", "Total laryngectomy", "TNM larynx"],
 [step("**Laryngeal cancer** is overwhelmingly squamous carcinoma from smoking and alcohol, subsited by lymphatics and presentation: glottic (true cords, sparse lymphatics, hoarseness early, best prognosis), supraglottic (rich lymphatics, late sore throat, otalgia, nodes, worse prognosis), subglottic (rarest, stridor late, worst). Any hoarseness over three weeks in smoker needs laryngoscopy; cord mobility (mobile, impaired, fixed) stages depth (T) because fixation means deep muscle or joint invasion.", "Hoarse smoker three weeks scopes. Glottis shouts early and cures; supraglottis whispers late with nodes."),
  step("Staging workup: flexible and operative laryngoscopy with biopsy, stroboscopy, CT or MRI larynx and neck (cartilage invasion, pre epiglottic and paraglottic spaces), chest imaging (second primary and metastases), nutrition, dental, speech swallow and smoking cessation. Transglottic tumours cross ventricle ignoring subsite borders. HPV plays minor role here unlike oropharynx; leukoplakia and dysplasia on cords are precursor surveillance lesions (voice preserving stripping decisions).", "Fixed cord stages deep. Scan cartilage and chest; smokers grow second cancers."),
  step("Early glottic cancer (T1 T2) cures equally by **radiotherapy** or transoral laser microsurgery (single modality, voice outcomes debated by tumour extent), preserving larynx. Advanced disease balances total laryngectomy (permanent stoma, voice rehabilitation by tracheoesophageal prosthesis electrolarynx or oesophageal speech) against chemoradiation organ preservation (RTOG pattern: concurrent cisplatin radiation spares anatomy in many, salvage surgery for failure, but nonfunctional preserved larynx with aspiration can be worse than laryngectomy). Choice is multidisciplinary with patient values, pulmonary reserve and salvage feasibility.", "Early cord cancer: beam or laser, keep voice box. Advanced: remove it or chemobeam and salvage failures."),
  step("Airway and aftercare dominate advanced care: impending obstruction needs awake tracheostomy (often before treatment, avoiding emergency cricothyrotomy through tumour), stoma education after laryngectomy (no voice without prosthesis, water drowning risk, heat moisture exchangers), hypothyroidism after neck radiation or hemithyroidectomy, and vigilance for pharyngocutaneous fistula post salvage (prior radiation, poor nutrition). Supraglottic tumours electively treat both neck sides even node negative due occult spread, unlike early glottic where neck observation is standard.", "Beam neck both sides for supraglottis even silent. After laryngectomy, voice comes via prosthesis valve.", tbl(["Subsite", "Lymphatics", "First symptom"], [["Glottic", "Sparse, nodes late", "Hoarseness early"], ["Supraglottic", "Rich bilateral", "Sore throat, nodes, otalgia"], ["Subglottic", "Paratracheal spread", "Stridor late"], ["Transglottic", "Crosses ventricle", "Mixed advanced signs"]]))],
 ["Hoarseness over 3 weeks in smoker: scope larynx", "Glottic early and node sparing; supraglottic nodal and bilateral neck", "Cord fixation upstages (deep invasion)", "Chemoradiation preserves organ, salvage laryngectomy rescues failure"],
 "Tobacco field change plus reflux and alcohol synergise squamous carcinogenesis on vibratory cord epithelium, while subsite lymphatic density and cartilage barriers channel spread patterns exploited by staging.",
 ["Glottic versus supraglottic by nodes and timing", "Laryngeal cancer versus chronic laryngitis (biopsy persistence)", "Organ preservation versus laryngectomy by function, not anatomy alone"],
 ["Laryngoscopy biopsy and stroboscopy, CT or MRI neck", "Chest CT for second primary in smokers", "Speech swallow, nutrition and thyroid baseline"],
 [mcq("bk2-ent-231", "Persistent hoarseness beyond 3 weeks in a smoker mandates what?", ["Voice rest 6 months", "Laryngoscopy to exclude carcinoma", "Inhaler trial", "Reassure as laryngitis"], 1, "Early glottic cancer declares only by hoarseness while curable; three week persistence threshold triggers scope in guidelines, especially smokers and drinkers. Chronic laryngitis diagnosis also requires visualisation.", ["Incorrect. Months delay upstages cancer.", "Correct. Scope after three weeks.", "Incorrect. Inhalers do not exclude tumour.", "Incorrect. Reassurance without scope unsafe."], "Three hoarse weeks in smoker: look at cords."),
  mcq("bk2-ent-232", "Glottic cancer enjoys best prognosis chiefly due to what two factors?", ["Rich lymphatics", "Early hoarseness presentation and sparse cord lymphatics delaying nodes", "HPV drive", "Young patients only"], 1, "True cords lack lymphatic drainage and voice change is immediate, so T1 glottic cures exceed 90 percent patterns with negligible nodal risk; supraglottic reverses both factors.", ["Incorrect. Rich nodes worsen supraglottic.", "Correct. Early symptom plus poor lymphatics.", "Incorrect. HPV minor in larynx.", "Incorrect. Patients are older smokers typically."], "Shouts early, spreads late: glottic luck."),
  mcq("bk2-ent-233", "Fixed vocal cord in laryngeal cancer signifies what staging implication?", ["T1 superficial", "Deep invasion (muscle, joint or cartilage spectrum) upstaging to at least T3 pattern", "Benign palsy unrelated", "Better prognosis"], 1, "Mobility loss means tumour invaded thyroarytenoid muscle, cricoarytenoid joint or beyond, defining advanced T categories and shifting toward combined modality or laryngectomy decisions.", ["Incorrect. T1 cord moves normally.", "Correct. Fixation equals deep invasion T3.", "Incorrect. In cancer context fixation is invasion until proven.", "Incorrect. Fixation worsens stage."], "Cord stuck means cancer deep."),
  mcq("bk2-ent-234", "Early T1 glottic carcinoma standard curative options preserving larynx are what?", ["Total laryngectomy mandatory", "Radiotherapy or transoral laser microsurgery (single modality)", "Chemotherapy alone", "Observation"], 1, "Both modalities cure similarly early; choice weighs voice quality, tumour exposure, patient preference, pulmonary status and salvage options in shared decision making.", ["Incorrect. Laryngectomy overtreats T1.", "Correct. Beam or laser, preserve larynx.", "Incorrect. Chemo alone insufficient.", "Incorrect. Cancer grows untreated."], "Small cord cancer: laser or beam, keep box."),
  mcq("bk2-ent-235", "Organ preservation chemoradiation for advanced larynx means which strategy and caveat?", ["Avoid surgery forever guaranteed", "Concurrent cisplatin radiation preserving larynx in responders, salvage laryngectomy for persistence or recurrence; preserved but nonfunctional larynx may aspirate", "Radiation halves dose", "Chemo replaces staging"], 1, "Landmark trials showed survival equivalence with larynx preservation in many, at cost of toxicity and need for salvage surgery readiness; function (swallow, airway) not just anatomy defines success.", ["Incorrect. Salvage surgery often required.", "Correct. Preserve responding organs, salvage failures.", "Incorrect. Full dose radiation used.", "Incorrect. Staging guides eligibility."], "Save box if it still works; cut if cancer stays."),
  mcq("bk2-ent-236", "After total laryngectomy, most effective alaryngeal voice method in modern practice is what?", ["Whisper only", "Tracheoesophageal prosthesis (surgical voice restoration) speech", "Writing only", "Normal voice returns"], 1, "One way valve prosthesis shunts pulmonary air to pharyngoesophageal segment producing fluent speech in most motivated patients; electrolarynx and oesophageal speech remain alternatives, stoma care education prevents water aspiration deaths.", ["Incorrect. Whisper lacks pulmonary drive post laryngectomy separation.", "Correct. Prosthesis valve speech leads.", "Incorrect. Writing supplements, not ceiling.", "Incorrect. Larynx removal permanently separates airway."], "Valve in stoma gives new voice."),
  mcq("bk2-ent-237", "Supraglottic cancer node negative neck management differs from early glottic how?", ["Observe both always", "Electively treat both neck sides (radiation or dissection) for supraglottic occult spread; early glottic neck usually observed", "Neck surgery for glottic T1 mandatory", "No neck imaging needed"], 1, "Rich bilateral supraglottic lymphatics hide occult metastases in fifth to third of cases justifying elective treatment, while T1 glottic nodal risk is under few percent.", ["Incorrect. Supraglottic observation under treats.", "Correct. Elective bilateral neck for supraglottic.", "Incorrect. Glottic T1 neck overtreatment avoided.", "Incorrect. Imaging stages both."], "Supraglottis drains rich: treat silent necks."),
  mcq("bk2-ent-238", "Impending airway obstruction from bulky laryngeal cancer safest securing method is what?", ["Blind oral intubation attempts repeated", "Awake tracheostomy under local anaesthesia (often planned before treatment)", "Sedation and observation", "Cricothyrotomy through tumour routinely"], 1, "Distorted tumour anatomy defeats intubation and cricothyrotomy may cut tumour (bleeding, poor landmarks); awake tracheostomy with patient breathing, ENT present, is controlled standard, sometimes becoming permanent if laryngectomy follows.", ["Incorrect. Blind attempts lose airway.", "Correct. Awake tracheostomy under local.", "Incorrect. Sedation obstructs completely.", "Incorrect. Through tumour is last resort harm."], "Tumour airway: awake tracheostomy, no heroics."),
  mcq("bk2-ent-239", "Subglottic cancer rarity and presentation pattern is what?", ["Commonest, hoarseness first", "Rarest subsite, late stridor and paratracheal spread, poorer prognosis", "Always paediatric", "Benign course"], 1, "Subglottic tumours (under 5 percent) grow silently in airway lumen until stridor, drain to paratracheal and mediastinal nodes, often needing laryngectomy with thyroid and node surgery.", ["Incorrect. Glottic commonest.", "Correct. Rare, late, stridorous subglottic.", "Incorrect. Paediatric subglottic lesions are haemangioma or stenosis.", "Incorrect. Malignant advanced behaviour."], "Rare below cords, arrives breathless."),
  mcq("bk2-ent-240", "White patch on vocal cord (leukoplakia) management principle in persistent smoker lesion is what?", ["Ignore as thrush always", "Biopsy or excisional stripping with histology for dysplasia grading and surveillance", "Radiotherapy immediately", "Antifungal forever"], 1, "Cord leukoplakia spans hyperkeratosis to invasive cancer clinically indistinguishable; microlaryngoscopic excision grades dysplasia guiding surveillance or treatment, smoking cessation central. Thrush scrapes and context differs.", ["Incorrect. Persistent cord patch may be dysplasia.", "Correct. Histology grades cord leukoplakia.", "Incorrect. Radiation needs cancer proof and staging.", "Incorrect. Fungus only one mimic."], "White cord patch earns microscope verdict.")]);

let fail = 0;
for (const m of M) {
  for (const s of m.steps) if (!s.tx.includes("**")) s.tx = "**Key point.** " + s.tx;
  const lesson = { v: 1, module: m.id, subject: "ent", title: m.title, minutes: 6, steps: m.steps, quiz: m.mcqs.map((x) => x.id), src: [], refs: [REF], gen: "AI", run: "books2-batch2p2-ent", model: "muse-wonder (local authoring, no external API)", checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: 10 } };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.log("LESSON FAIL", m.id, probs); fail++; }
  fs.writeFileSync(path.join(ROOT, "prep/lessons/v1", m.id + ".json"), JSON.stringify(lesson, null, 1));
  const kb = { id: m.kb, name: m.kbName, aliases: m.aliases, class: "non_infective", system: "ENT", specialty: "ENT", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "8th edition topic map (2026-10-13)", pages: null, clinicalPearls: m.pearls, pathophysiology: m.patho, additionalDifferentials: m.diffs, additionalInvestigations: m.invs } };
  fs.writeFileSync(path.join(ROOT, "kb/reference", m.kb + ".json"), JSON.stringify(kb, null, 1));
  const overlay = { topic: m.id, set: "maikbook2", v: 1, items: m.mcqs.map((x) => ({ prov: "SMD", gen: "hand", set: "maikbook2", d: 2, cog: "application", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } }, id: x.id, q: x.q, o: x.o, a: x.a, exp: x.exp, r: x.r, kp: x.kp })) };
  const dir = path.join(ROOT, "prep/overlays/maikbook2/ent");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, m.id + ".json"), JSON.stringify(overlay, null, 1));
}
const ixPath = path.join(ROOT, "prep/lessons/v1/index.json");
const ix = JSON.parse(fs.readFileSync(ixPath, "utf8"));
for (const m of M) ix.modules[m.id] = { title: m.title, minutes: 6, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(ixPath, JSON.stringify(ix, null, 1));
const ocPath = path.join(ROOT, "prep/bank/overlay-counts.json");
const oc = JSON.parse(fs.readFileSync(ocPath, "utf8"));
oc.sets.maikbook2 = oc.sets.maikbook2 || {}; oc.sets.maikbook2.ent = oc.sets.maikbook2.ent || {};
for (const m of M) oc.sets.maikbook2.ent[m.id] = 10;
fs.writeFileSync(ocPath, JSON.stringify(oc, null, 1));
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "lesson failures:", fail);
if (fail) process.exit(1);
